  ('associate-foundations', 1, 'library-desk', 'library', 'workbench', 'Set up a shared reference desk', 'Four librarians draft independently but need the same policy and style.', 'prototype-v1'),
  ('associate-foundations', 1, 'school-notice-pilot', 'school', 'workbench', 'Fix the school’s notice workflow', 'Families are getting inconsistent answers. Jordan wants a pilot with evidence of saved work.', 'prototype-v1'),
  ('associate-foundations', 1, 'library-activity-kit', 'library', 'workbench', 'Build an activity kit for the library', 'Staff want a reusable kit for programs and a reliable way to carry confirmed information across teams.', 'prototype-v1'),
  ('associate-foundations', 1, 'kitchen-billing-audit', 'restaurant', 'workbench', 'Recover the weekly billing summary', 'Refunds disappeared after a vendor export changed. Lina also needs a cheaper and repeatable review process.', 'prototype-v1'),
  ('associate-foundations', 1, 'community-policy', 'community', 'workbench', 'Protect applicants while reducing queue time', 'Malik wants help organizing applications and improving a slow referral process.', 'prototype-v1'),
  ('associate-foundations', 1, 'enrollment-replies', 'school', 'original', 'Prepare enrollment replies', 'Families need answers from the current bulletin and a clear route for exceptions.', 'prototype-v1');
