insert into certcity_private.item_revisions (track_id, release_no, item_id, family_id, blueprint_version, domain_no, objective_no, source_url, prompt, rubric) values
  ('associate-foundations', 1, 'bus-notice', 'bus-notice', '2026-07.v1', 1, 1, 'https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/overview', '{"scenario":"Maplewood School","prompt":"A road closure changes stops on two bus routes. The transport memo gives times but omits the date service resumes. Families need a 100-word notice today. Which instruction best fits?","options":[["a","Draft a short notice in last month’s format and use the usual closure period where the memo is incomplete."],["b","Write for families in 100 words using only the memo. List affected stops and times and mark the reopening date as unconfirmed."],["c","Summarize the memo for the transport director, then ask Claude to make the summary more conversational."],["d","Include the affected routes and use the road contractor’s public timeline to fill the missing date."]]}', '{"correct":["b"],"explanation":"Define the audience, length, source and rule for missing facts. The reopening date is still unknown.","rationales":{"a":"The format helps, but the usual period is unsupported.","b":"This keeps the actionable details and preserves the uncertainty.","c":"A director’s summary can omit stop-level details families need.","d":"Road work and resumption of bus service can have different dates."}}'),
  ('associate-foundations', 1, 'two-policy-dates', 'two-policy-dates', '2026-07.v1', 2, 3, 'https://platform.claude.com/docs/en/test-and-evaluate/strengthen-guardrails/reduce-hallucinations', '{"scenario":"Maplewood School","prompt":"A draft says applications close May 14. Its citation opens an approved memo that says May 14 for transfers and May 24 for new enrollments. The recipient is enrolling for the first time. What should staff verify before sending?","options":[["a","Confirm the memo is the latest published version and keep the cited date."],["b","Ask Claude to search the memo again and accept the date if it repeats the same result."],["c","Check the recipient category against the memo, then use the deadline for new enrollments."],["d","Link the full memo and leave both dates in the reply without describing the categories."]]}', '{"correct":["c"],"explanation":"A real citation can still support the wrong claim. Check its population and date against the intended recipient.","rationales":{"a":"A current memo can specify different deadlines for different groups.","b":"A repeat answer can repeat the same scope error.","c":"This validates both applicability and the date.","d":"The reader still cannot tell which date applies."}}'),
  ('associate-foundations', 1, 'shared-faq', 'shared-faq', '2026-07.v1', 3, 1, 'https://support.claude.com/en/articles/9519177-how-can-i-create-and-manage-projects', '{"scenario":"Lucas Branch Library","prompt":"Five librarians answer program questions in separate Claude chats. All five need the same approved FAQ and instructions for referring exceptions. They do not need to see one another’s draft conversations. How should the team set this up?","options":[["a","Put the FAQ in the first chat and ask each librarian to start another chat in the same Project."],["b","Publish an Artifact with a sample answer and ask each librarian to copy its style."],["c","Create one continuing chat with all librarians’ draft replies and a pinned copy of the FAQ."],["d","Use a shared Project with the FAQ in project knowledge and the referral rule in project instructions."]]}', '{"correct":["d"],"explanation":"Project knowledge and instructions give separate chats the same approved starting point.","rationales":{"a":"One chat’s attachments and messages are not shared project knowledge.","b":"An example does not provide the full approved FAQ or referral instructions.","c":"This mixes case histories when only reference material needs to be shared.","d":"New chats can use both resources without inheriting other case histories."}}'),
  ('associate-foundations', 1, 'review-window', 'review-window', '2026-07.v1', 4, 4, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"Market Hall","prompt":"Stall operators send a weekly update. A staff member must approve changes to operating hours. Drafting consumes four hours and reviewing takes 30 minutes. The director wants a small pilot with the existing approval step. Which design fits?","options":[["a","Draft from stall forms, retain staff approval, and compare time and corrections with the baseline."],["b","Use Claude to approve routine hour changes and have staff review a weekly sample."],["c","Have staff draft as usual and let Claude approve only changes below a time threshold."],["d","Run a separate drafting trial on polished past updates and count the time Claude takes to respond."]]}', '{"correct":["a"],"explanation":"Keep the accountable reviewer and compare the complete process with a baseline.","rationales":{"a":"This measures saved work and catches extra review effort.","b":"Sampling does not satisfy prepublication approval.","c":"The approval requirement applies to every change.","d":"This misses review and the difficulty of raw submissions."}}'),
  ('associate-foundations', 1, 'superseded-policy', 'superseded-policy', '2026-07.v1', 5, 4, 'https://support.claude.com/en/articles/9519177-how-can-i-create-and-manage-projects', '{"scenario":"Lucas Community Center","prompt":"A Project cites last season’s room rules in new replies. Both the old and new PDFs are in project knowledge. Only the new rules apply to future bookings. What should the coordinator change first?","options":[["a","Keep both PDFs and change the output format so every answer includes a citation."],["b","Archive the old PDF outside the Project, date the current source, and test a booking where the rule changed."],["c","Start fresh chats while keeping both documents and add the word ‘latest’ to each request."],["d","Move the new policy into a separate draft chat and leave the Project for live replies."]]}', '{"correct":["b"],"explanation":"Remove the conflicting document from active knowledge, identify the current policy and verify a case that distinguishes the versions.","rationales":{"a":"Citations expose conflicts but do not remove the superseded source.","b":"This fixes the input and checks the exact regression.","c":"The old source remains eligible and ‘latest’ depends on metadata.","d":"The live replies continue to use the conflicting corpus."}}'),
  ('associate-foundations', 1, 'field-minimum', 'field-minimum', '2026-07.v1', 6, 2, 'https://trust.anthropic.com/', '{"scenario":"Maplewood School","prompt":"The school allows an approved workspace to classify enrollment messages by topic. Its policy excludes student IDs and medical details. Staff only need topic counts. Which two steps support that pilot?","options":[["a","Keep the minimum topic-bearing excerpts and remove identifiers and medical details before uploading."],["b","Upload original messages and request topic counts with no identifiers in the output."],["c","Replace student names with initials but retain IDs so messages can be deduplicated in Claude."],["d","Confirm the proposed input fields and workspace with the school’s designated owner before piloting."],["e","Put the raw messages in project knowledge rather than attaching them to the prompt."]]}', '{"correct":["a","d"],"explanation":"Remove unnecessary sensitive fields before processing and verify the exact workflow falls within approved policy.","rationales":{"a":"This minimizes the inputs to the allowed task.","b":"The excluded data would already have been sent as input.","c":"Student IDs are explicitly excluded. Deduplication can happen locally.","d":"Workspace approval does not independently approve every input or use.","e":"Changing where the content is added does not change what is disclosed."}}'),
  ('associate-foundations', 1, 'before-after', 'before-after', '2026-07.v1', 7, 1, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"Juniper Kitchen","prompt":"A weekly summary started omitting refunds on Monday. The prompt and model are unchanged. The export switched refunds from negative amounts to positive amounts with a new type field. Which next step best isolates the problem?","options":[["a","Switch models, rerun Monday’s export and keep whichever model finds more refunds."],["b","Add a broad instruction to look harder for missing rows and compare total word counts."],["c","Compare matched rows in both formats and test how the new type field affects classification."],["d","Split Monday’s file into smaller pieces and compare summaries against one another."]]}', '{"correct":["c"],"explanation":"Change one input condition while holding the model and instructions constant. Then teach the verified new representation.","rationales":{"a":"A model swap does not test the suspected input change.","b":"Length is unrelated to refund accuracy.","c":"This tests the suspected cause and verifies the fix.","d":"Splitting does not resolve the meaning of the new field."}}'),
  ('associate-foundations', 1, 'interview-plan', 'interview-plan', '2026-07.v1', 1, 2, 'https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/overview', '{"scenario":"Neighborhood Council","prompt":"Council members have 18 interview notes and must recommend two service changes. Three notes conflict about the same opening hour. Which sequence best preserves the evidence?","options":[["a","Draft recommendations, then find notes supporting each recommendation."],["b","Summarize the notes into one narrative and ask for two recommendations from the summary."],["c","Extract observations with note IDs, compare the conflicting reports, then recommend changes with the conflict flagged."],["d","Ask three chats to recommend changes independently and use a majority vote to settle the opening hour."]]}', '{"correct":["c"],"explanation":"Extract source-linked observations before comparing them. Keep unresolved conflicts visible in the recommendation.","rationales":{"a":"This can exclude contrary evidence.","b":"The narrative can flatten the disagreement before it is assessed.","c":"This keeps the evidence auditable throughout.","d":"Agreement across chats cannot determine which factual report is correct."}}'),
  ('associate-foundations', 1, 'missing-shifts', 'missing-shifts', '2026-07.v1', 2, 2, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"City Dispatch","prompt":"A summary says most staff favor a new schedule. It cites 32 survey responses, all from weekday shifts. Weekend staff work under different constraints. What can the supervisor publish now?","options":[["a","Publish the overall claim with the number of responses in a footnote."],["b","Describe the finding as weekday respondents’ preference and flag that weekend feedback is still needed."],["c","Reweight the 32 responses by the proportion of weekend staff."],["d","Ask Claude to estimate weekend preferences from its general understanding of shift work."]]}', '{"correct":["b"],"explanation":"Restrict the claim to the observed population. Collect weekend evidence before claiming a staff-wide preference.","rationales":{"a":"The count does not explain the missing group.","b":"The language matches the actual sample.","c":"Weighting cannot supply responses for an entirely absent group.","d":"An estimate from general patterns is not evidence about this staff."}}'),
  ('associate-foundations', 1, 'rota-model', 'rota-model', '2026-07.v1', 3, 3, 'https://platform.claude.com/docs/en/models/overview', '{"scenario":"Market Hall","prompt":"A helper sorts vendor emails into 12 fixed categories. A trial found all tested Claude models meet the target on routine mail. Only ambiguous messages need better judgment. Staff have a hard budget and can review flagged items. Which rollout is most appropriate?","options":[["a","Use the lowest-cost tested model for routine mail and send ambiguous cases to staff. Audit the routing."],["b","Use the highest-capability model for every message and reduce sample review to offset its cost."],["c","Use the lowest-cost model for all mail and treat an assigned category as proof of clarity."],["d","Alternate models by day and keep the one that handles the most messages per hour."]]}', '{"correct":["a"],"explanation":"Use the least costly option that meets the measured routine target. Monitor flagged and missed exceptions.","rationales":{"a":"It meets the measured requirement and preserves a path for hard cases.","b":"The trial found no routine benefit and reducing review weakens oversight.","c":"The model can confidently assign the wrong category.","d":"Day-level traffic differences and throughput alone cannot show quality."}}'),
  ('associate-foundations', 1, 'pilot-brief', 'pilot-brief', '2026-07.v1', 4, 5, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"Maplewood School","prompt":"A trial reduced drafting time from 12 to 5 minutes. Review time rose from 2 to 6 minutes. Two of 30 drafts needed policy corrections before sending. Which summary should the project lead give the principal?","options":[["a","The pilot saved seven minutes per message, and staff caught all errors."],["b","The pilot saved 58% of staff time. Keep review as an optional safeguard."],["c","Review time tripled, so the pilot reduced overall productivity."],["d","Total time fell by three minutes per reply. Staff corrected two of 30 drafts."]]}', '{"correct":["d"],"explanation":"The measured total fell from 14 to 11 minutes. Report the observed error and review burden.","rationales":{"a":"Seven minutes covers drafting only, and the trial cannot establish all possible errors were caught.","b":"The 58% figure applies to drafting time, and policy errors were found in review.","c":"This ignores the larger reduction in drafting time.","d":"This accounts for both workflow stages and the observed quality issue."}}'),
  ('associate-foundations', 1, 'persistent-rules', 'persistent-rules', '2026-07.v1', 5, 3, 'https://support.claude.com/en/articles/9519177-how-can-i-create-and-manage-projects', '{"scenario":"Lucas Branch Library","prompt":"In an approved shared Project, every new program reply must list accessibility contact details and use plain language. The reference document changes monthly. Where should staff maintain these two types of information?","options":[["a","Put the behavior in project instructions and keep the current reference document in project knowledge."],["b","Put the behavior in the title of the reference document and refresh that file monthly."],["c","Record both in one successful chat and link it from a new Project each month."],["d","Keep both in a reusable output draft and tell staff to edit it after Claude responds."]]}', '{"correct":["a"],"explanation":"Use instructions for durable behavior and project knowledge for the changing reference material.","rationales":{"a":"Every project chat receives the durable instructions and can use the current reference.","b":"A title is a weak and incidental place to specify required output.","c":"The prior chat does not automatically supply instructions and knowledge to new ones.","d":"This leaves required behavior out of the model’s instructions."}}'),
  ('associate-foundations', 1, 'volunteer-ranking', 'volunteer-ranking', '2026-07.v1', 6, 1, 'https://platform.claude.com/docs/en/test-and-evaluate/strengthen-guardrails/mitigate-jailbreaks', '{"scenario":"Lucas Community Center","prompt":"The board wants Claude to rank volunteers for limited training slots. Center policy requires staff to apply published criteria and record reasons. Where can Claude contribute under that policy?","options":[["a","Rank applicants using the criteria and send staff only applicants within one point of the cutoff."],["b","Extract cited application evidence into the criteria worksheet and have staff score and record each decision."],["c","Have Claude rank anonymized applications and use the ranking when reviewers disagree."],["d","Ask Claude for a separate ranking and adopt it whenever it agrees with one reviewer."]]}', '{"correct":["b"],"explanation":"Organize evidence for review and keep the decision with the people responsible for applying the criteria.","rationales":{"a":"The model would decide most outcomes without staff review.","b":"Staff remain accountable and can verify the evidence.","c":"Anonymization does not transfer decision authority to the model.","d":"Model agreement does not fulfill the documented staff decision process."}}'),
  ('associate-foundations', 1, 'stable-brief', 'stable-brief', '2026-07.v1', 7, 3, 'https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/overview', '{"scenario":"Washington Printworks","prompt":"Staff retype the same six requirements for every proof review. The requirements are stable, but the artwork and order number change each time. Misses usually trace to an omitted instruction. What change should be tested first?","options":[["a","Combine the last ten proof chats into one continuing conversation."],["b","Raise the output length so Claude has space to mention every requirement."],["c","Use a shared review template with fields for the current order and compare omissions on matched proofs."],["d","Ask staff to include the requirements in free-form notes and have Claude restate them first."]]}', '{"correct":["c"],"explanation":"Put repeatable instructions in one maintained template and measure missed requirements and total time.","rationales":{"a":"Prior cases add context without ensuring the requirements are carried forward accurately.","b":"Output length cannot restore a requirement missing from the input.","c":"It directly addresses copy omissions and verifies the effect.","d":"It retains the manual copying step causing the errors."}}'),
  ('associate-foundations', 1, 'paired-tones', 'paired-tones', '2026-07.v1', 1, 3, 'https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/overview', '{"scenario":"Maplewood School","prompt":"The first draft sounds accusatory when an application is incomplete. A rewrite became friendlier but removed the missing-document list. Which iteration should staff test?","options":[["a","Ask for a friendlier reply and review only the opening line."],["b","Repeat the original prompt at a higher effort setting."],["c","Show a neutral example and require the verified document list to stay intact."],["d","Provide a friendly unrelated email as the only source."]]}', '{"correct":["c"],"explanation":"Keep the verified content invariant while giving a concrete example of the tone change.","rationales":{"a":"The document list can disappear again.","b":"Extra effort does not describe the requested tone.","c":"The revised prompt states what changes and what must survive.","d":"Its tone can transfer, but it lacks the required facts."}}'),
  ('associate-foundations', 1, 'different-deliverables', 'different-deliverables', '2026-07.v1', 1, 4, 'https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/overview', '{"scenario":"Neighborhood Council","prompt":"The council needs ideas for a future event and a separate summary of what the budget committee approved. Which pair of instructions matches the two tasks?","options":[["a","Brainstorm within event constraints. Summarize approvals directly from the minutes."],["b","Require minute citations for every new idea and infer approval from earlier events."],["c","Ask for one confident recommendation covering both tasks."],["d","Use the event idea draft as the main source for the approval summary."]]}', '{"correct":["a"],"explanation":"Allow invention for brainstorming. Restrict the factual summary to the approved record.","rationales":{"a":"Each prompt fits the task’s evidence requirements.","b":"It constrains invention in the wrong place and weakens the factual claim.","c":"It can merge proposals with approved decisions.","d":"Proposals are not records of approval."}}'),
  ('associate-foundations', 1, 'fee-and-hours', 'fee-and-hours', '2026-07.v1', 2, 1, 'https://platform.claude.com/docs/en/test-and-evaluate/strengthen-guardrails/reduce-hallucinations', '{"scenario":"Community Center","prompt":"A room reply states the correct deposit but omits the refundable cutoff. The caller asked about both. Which check should the coordinator use across future replies?","options":[["a","Verify only the amount because it is the highest-risk field."],["b","Use reply length as a proxy for coverage."],["c","Confirm the policy link resolves and accept the reply."],["d","Check both the deposit and the cutoff against the approved policy."]]}', '{"correct":["d"],"explanation":"Check required fields and support for each against the same authoritative policy.","rationales":{"a":"This would miss the observed omission.","b":"A longer reply can still omit a required fact.","c":"The link does not show that every requested fact is present.","d":"It tests both completeness and correctness."}}'),
  ('associate-foundations', 1, 'outdated-route', 'outdated-route', '2026-07.v1', 2, 4, 'https://platform.claude.com/docs/en/test-and-evaluate/strengthen-guardrails/reduce-hallucinations', '{"scenario":"Transit service desk","prompt":"Claude’s reroute draft matches the current map, but a same-day dispatch note reports a stop moved and has no signed replacement location. What is the next step before publishing directions?","options":[["a","Publish the map’s stop because the map is the standard reference."],["b","Ask dispatch to confirm the location and hold the disputed direction until verified."],["c","Publish the dispatch note as the new direction."],["d","Ask Claude for the most likely replacement stop using nearby routes."]]}', '{"correct":["b"],"explanation":"An unresolved conflict affecting a live route needs confirmation from its responsible owner.","rationales":{"a":"The same-day report calls its current accuracy into question.","b":"It resolves the relevant operational uncertainty before publication.","c":"It contains no verified replacement location.","d":"Inference cannot confirm an operational decision."}}'),
  ('associate-foundations', 1, 'one-decision-two-audiences', 'one-decision-two-audiences', '2026-07.v1', 2, 5, 'https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/overview', '{"scenario":"Market Hall","prompt":"Staff need exact instructions for the new closing process. Vendors need a short announcement. The same two new times must appear in both. How should the draft be revised?","options":[["a","Publish the full operations checklist to both audiences."],["b","Ask for separate creative rewrites and let each simplify the times."],["c","Draft staff steps and a vendor notice from one verified list of the new times."],["d","Use the short notice as the entire staff procedure."]]}', '{"correct":["c"],"explanation":"Change vocabulary and detail by audience while preserving the same operative facts.","rationales":{"a":"Vendors receive details they do not need.","b":"The operative times can diverge.","c":"It gives each audience the right level of detail without changing the facts.","d":"It omits the steps staff need to apply the change."}}'),
  ('associate-foundations', 1, 'reusable-checklist', 'reusable-checklist', '2026-07.v1', 2, 6, 'https://support.claude.com/en/articles/17153992-what-are-artifacts-and-how-do-i-use-them', '{"scenario":"Washington Printworks","prompt":"Two colleagues need to iterate on a checklist as a standalone document during a Claude conversation. A downstream importer separately needs a machine-readable array of item IDs. Which output pairing fits?","options":[["a","Use an Artifact for the editable checklist and a structured JSON array for the importer."],["b","Use one long inline reply and ask the importer to infer the IDs from prose."],["c","Use a screenshot for the checklist and a second screenshot for the IDs."],["d","Store both only in Project instructions."]]}', '{"correct":["a"],"explanation":"Choose an editable standalone Artifact for the working checklist and a structured format for machine consumption.","rationales":{"a":"The formats match the two different consumers.","b":"The parser does not get the expected structure.","c":"The outputs are harder to revise and parse.","d":"Instructions shape outputs but are not the required deliverables."}}'),
  ('associate-foundations', 1, 'model-families-trial', 'model-families-trial', '2026-07.v1', 3, 2, 'https://platform.claude.com/docs/en/models/overview', '{"scenario":"Lucas Branch Library","prompt":"A librarian can test only two Claude model families this week. One job is high-volume tagging with simple labels. The other is a small number of demanding cross-document comparisons. Which first comparison makes sense?","options":[["a","Start with Opus for tagging and Haiku for hard comparisons, optimizing each on throughput alone."],["b","Use a single family for both and estimate cost from the number of chats."],["c","Select the newest available model for both without a representative trial."],["d","Trial Haiku on routine tagging and Opus on complex comparisons, then compare each with labeled examples and budget."]]}', '{"correct":["d"],"explanation":"Start with a speed-oriented family for routine work and a higher-capability family for complex work. Verify against real examples.","rationales":{"a":"This reverses the initial candidates and ignores comparison quality.","b":"This leaves the task differences untested and ignores actual usage.","c":"Release recency does not establish fit.","d":"This tests the relevant strengths and constraints."}}'),
  ('associate-foundations', 1, 'handoff-context', 'handoff-context', '2026-07.v1', 3, 4, 'https://support.claude.com/en/articles/9519177-how-can-i-create-and-manage-projects', '{"scenario":"Market Hall planning","prompt":"A long chat mixes two event plans. The second team wants a fresh conversation and access to verified dates, but should not inherit brainstorming about the first event. What should the coordinator do?","options":[["a","Continue the old thread and ask Claude to forget half of it."],["b","Create a clean chat and provide a short, verified brief with the relevant dates."],["c","Start a clean chat with no brief and assume the previous dates are available."],["d","Copy the full conversation into Project knowledge for every future case."]]}', '{"correct":["b"],"explanation":"Carry forward verified material explicitly, then work from a clean conversation.","rationales":{"a":"The unrelated history remains in context.","b":"It preserves essential state without importing unrelated brainstorming.","c":"The needed facts are not guaranteed to transfer.","d":"It makes unrelated, unverified discussion broadly available."}}'),
  ('associate-foundations', 1, 'where-to-pilot', 'where-to-pilot', '2026-07.v1', 4, 1, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"Washington Printworks","prompt":"A manager wants Claude to improve proof handling. Staff report that checking color references takes two minutes, approvals wait a day, and most rework comes from mismatched job numbers. What should the manager do first?","options":[["a","Automate approvals because they have the longest wait."],["b","Select a model by advertised speed and apply it to all stages."],["c","Map proof handling and test where job numbers can be checked under the existing approval policy."],["d","Redesign the reporting format and use adoption as the only measure."]]}', '{"correct":["c"],"explanation":"Establish the actual bottleneck and constraints before picking an intervention.","rationales":{"a":"Waiting does not show that approval can safely be delegated.","b":"Model speed does not identify the costly error or approval dependency.","c":"It ties the pilot to observed failure and a real constraint.","d":"Adoption would not show reduced rework."}}'),
  ('associate-foundations', 1, 'wait-time-breakdown', 'wait-time-breakdown', '2026-07.v1', 4, 2, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"Community Center","prompt":"Room bookings average two days. Logs show ten minutes of drafting, a one-day staff queue, and delays when a form omits dates. What is the most informative next analysis?","options":[["a","Measure Claude’s drafting speed and use it to forecast the full turnaround."],["b","Compare processing and waiting times for complete versus incomplete forms."],["c","Remove the approval queue from the measurement because Claude cannot change it."],["d","Replace the current process with automatic booking and compare volumes."]]}', '{"correct":["b"],"explanation":"Use logs to distinguish waiting from processing, then compare changes aimed at the observed causes.","rationales":{"a":"Drafting is a small part of the wait.","b":"This isolates a documented cause and retains the required control.","c":"The wait still affects the outcome the center cares about.","d":"It changes several variables and bypasses existing review."}}'),
  ('associate-foundations', 1, 'prototype-order', 'prototype-order', '2026-07.v1', 4, 3, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"Neighborhood Council","prompt":"Residents often leave a date out of service requests. The council can test a form change and a Claude draft step, but cannot change its referral rules this month. How should the team iterate?","options":[["a","Require the date, draft from the form, and compare omissions while keeping staff referral."],["b","Use a richer prompt to infer missing dates and approve referrals automatically."],["c","Build a new referral system first and compare total staff logins."],["d","Revise both every day without recording what changed."]]}', '{"correct":["a"],"explanation":"Prototype the editable parts and compare specific failure rates with the current process.","rationales":{"a":"It addresses the known defect within the fixed policy.","b":"It introduces unsupported facts and changes the referral rule.","c":"The permitted change does not include referrals and logins miss the defect.","d":"The team cannot attribute any improvement."}}'),
  ('associate-foundations', 1, 'project-setup', 'project-setup', '2026-07.v1', 5, 1, 'https://support.claude.com/en/articles/9519177-how-can-i-create-and-manage-projects', '{"scenario":"Lucas Branch Library","prompt":"A new team Project needs catalog terms and a consistent response template. New staff should get both as soon as they open a chat in that Project. Which setup supplies them?","options":[["a","Create a reusable chat title naming the terms and template."],["b","Upload the template and terms to a personal chat shared as a link."],["c","Put everything in the first message of each new chat."],["d","Put catalog terms in project knowledge and the template in project instructions."]]}', '{"correct":["d"],"explanation":"Store reference content as project knowledge and response behavior as project instructions.","rationales":{"a":"A title does not supply the content or instructions.","b":"That is a separate conversation rather than new Project context.","c":"It duplicates maintenance and can vary across staff.","d":"The resources are maintained once for the intended workspace."}}'),
  ('associate-foundations', 1, 'connector-access', 'connector-access', '2026-07.v1', 5, 2, 'https://support.claude.com/en/articles/9519177-how-can-i-create-and-manage-projects', '{"scenario":"Regional arts office","prompt":"A program team wants Claude to reference a shared folder and exclude a restricted sibling folder. Both contain similarly named handbooks. What should the team verify before adding a connector?","options":[["a","Connect the broadest account and list the sibling folder as off-limits in the prompt."],["b","Give both folders the same label and ask Claude to prefer the newer date."],["c","Confirm the connector’s authorized scope and verify a test query uses only the approved folder’s current handbook."],["d","Use a teammate’s account that already has both folders and rely on manual review of citations."]]}', '{"correct":["c"],"explanation":"Review data access and source authority before depending on connected retrieval.","rationales":{"a":"A prompt is not an access control.","b":"Naming does not restrict which records can be seen.","c":"It checks access as well as source selection.","d":"Review after retrieval cannot prevent exposure."}}'),
  ('associate-foundations', 1, 'exception-owner', 'exception-owner', '2026-07.v1', 6, 3, 'https://trust.anthropic.com/', '{"scenario":"Juniper Kitchen","prompt":"The company allows anonymized supplier notes in Claude but requires written approval before connecting a shared mailbox. A teammate has an active connector for a different department. What should happen before using it here?","options":[["a","Use the existing connector since the company already approved it somewhere."],["b","Get the required approval for this mailbox and scope before enabling access."],["c","Connect the mailbox and ask Claude to anonymize what it retrieves."],["d","Connect during the pilot, then request approval if the results justify it."]]}', '{"correct":["b"],"explanation":"Apply the organization’s approval rule to the proposed access and purpose.","rationales":{"a":"Approval for one department does not authorize this use.","b":"It follows the policy for the actual connector use.","c":"Mailbox access would already occur before approval.","d":"The requirement applies before access."}}'),
  ('associate-foundations', 1, 'language-effects', 'language-effects', '2026-07.v1', 6, 4, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"Lucas Community Center","prompt":"Claude’s first draft flags six residents as ‘uncooperative’ because their requests use short sentences. Staff must sort by the service needed. What should the coordinator do?","options":[["a","Keep the labels but avoid showing them to residents."],["b","Use Claude to infer which residents prefer shorter messages and retain the labels internally."],["c","Review only the longest requests because they contain more evidence."],["d","Route by explicit service facts, check short and long requests for uneven errors, and let staff correct routing."]]}', '{"correct":["d"],"explanation":"Remove the unsupported judgment, test across writing styles, and keep staff review of consequential routing.","rationales":{"a":"Hidden labels still influence treatment.","b":"The inference has no supporting evidence and the judgment remains.","c":"The observed error affects short messages.","d":"This addresses the task and measures the observed risk."}}'),
  ('associate-foundations', 1, 'correction-codes', 'correction-codes', '2026-07.v1', 7, 2, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"Harbor events office","prompt":"Staff reviewed 40 drafts. Nine edits all corrected the same outdated venue rule; the other three were independent style changes. Which revision should be tried first?","options":[["a","Update the venue rule and rerun examples that depended on it."],["b","Add the style edits first because they are easier to automate."],["c","Put the entire review log into every prompt as examples."],["d","Measure whether the next drafts contain fewer words."]]}', '{"correct":["a"],"explanation":"Prioritize the repeated substantive failure, then recheck the exact cases it affected.","rationales":{"a":"The change targets the common cause and makes it testable.","b":"They do not address the nine policy corrections.","c":"This repeats unrelated edits and may retain stale guidance.","d":"Length cannot establish policy accuracy."}}'),
  ('associate-foundations', 1, 'gallery-label', 'gallery-label', '2026-07.v1', 1, 1, 'https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/overview', '{"scenario":"Harbor Gallery","prompt":"A curator needs an 80-word label for children. The object record gives a known maker and an approximate date. How should the curator brief Claude?","options":[["a","Ask for an engaging label and let Claude supply a precise year from historical context."],["b","Use the object record, write 80 words for children, and keep the date approximate."],["c","Use an academic description and simplify only the longest sentences."],["d","Use two sample labels and infer missing facts from objects of the same era."]]}', '{"correct":["b"],"explanation":"State the audience and limit, and preserve what the record knows and how precisely it knows it.","rationales":{"a":"The record does not support a precise year.","b":"It specifies a deliverable and protects source precision.","c":"Sentence length alone does not adapt vocabulary or emphasis.","d":"Examples can guide style, but cannot establish missing facts."}}'),
  ('associate-foundations', 1, 'rebate-claim', 'rebate-claim', '2026-07.v1', 2, 3, 'https://platform.claude.com/docs/en/test-and-evaluate/strengthen-guardrails/reduce-hallucinations', '{"scenario":"Energy Advice Desk","prompt":"A draft says every household gets a rebate. The linked source says up to $200 for households under an income cap. Which edit is supported?","options":[["a","Say every household can expect up to $200."],["b","Say eligible households receive $200."],["c","Say eligible households may receive up to $200 and link to the criteria."],["d","Remove the amount and say the rebate is open to everyone."]]}', '{"correct":["c"],"explanation":"Both the eligibility condition and the maximum amount change what can be promised.","rationales":{"a":"The amount is capped but the eligibility claim is still too broad.","b":"Eligibility alone does not guarantee the maximum.","c":"This preserves both restrictions.","d":"Removing the figure does not fix eligibility."}}'),
  ('associate-foundations', 1, 'chapter-handoff', 'chapter-handoff', '2026-07.v1', 3, 1, 'https://support.claude.com/en/articles/9519177-how-can-i-create-and-manage-projects', '{"scenario":"Orchard Press","prompt":"Editors work on separate chapters in separate chats. Each needs the same style guide and glossary. Where should the stable references live?","options":[["a","Add the style guide and glossary to the shared Project’s knowledge."],["b","Attach both documents to the first chapter chat."],["c","Put one example chapter in an Artifact."],["d","Enable a longer conversation and keep all chapters in one thread."]]}', '{"correct":["a"],"explanation":"Project knowledge makes a reference available across chats and keeps it distinct from one chapter’s history.","rationales":{"a":"New chats can use both documents.","b":"Other chats do not inherit the attachments.","c":"An example does not expose the complete guide and glossary.","d":"It mingles chapter-specific context and does not meet the separate-chat requirement."}}'),
  ('associate-foundations', 1, 'order-proof', 'order-proof', '2026-07.v1', 4, 4, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"Bay Street Bakery","prompt":"Claude can draft confirmations from order forms. The owner requires a person to check allergy notes before sending. Which pilot measures impact while meeting that requirement?","options":[["a","Send high-confidence confirmations and audit a sample at week end."],["b","Review orders only when the draft contains an allergy note."],["c","Have staff draft as usual and measure how fast Claude can read an order."],["d","Draft from forms, verify allergy notes before sending, and record review effort."]]}', '{"correct":["d"],"explanation":"Keep the mandated review for every case and measure time after review as well as drafting.","rationales":{"a":"A retrospective audit misses the required review before sending.","b":"A missing note in the draft could hide a relevant source note.","c":"This does not measure a changed workflow.","d":"This tests the workflow under the real review condition."}}'),
  ('associate-foundations', 1, 'closing-checklist', 'closing-checklist', '2026-07.v1', 5, 4, 'https://support.claude.com/en/articles/9519177-how-can-i-create-and-manage-projects', '{"scenario":"Marina Operations","prompt":"Replies sometimes cite a closing checklist withdrawn last month. It and the current checklist are both in Project knowledge. Which intervention tests the root cause?","options":[["a","Repeat the request in a new chat with the same Project sources."],["b","Remove the withdrawn file and test a rule that changed."],["c","Keep both and require numbered bullet points in every answer."],["d","Use a stronger model with the same two checklists."]]}', '{"correct":["b"],"explanation":"Keep one active source and test a case on which the two versions produce different answers.","rationales":{"a":"A new chat still has access to both checklists.","b":"The test distinguishes a successful fix from chance agreement.","c":"Formatting does not resolve source authority.","d":"Model capability does not resolve an unspecified authority conflict."}}'),
  ('associate-foundations', 1, 'notes-policy', 'notes-policy', '2026-07.v1', 6, 2, 'https://trust.anthropic.com/', '{"scenario":"Regional Food Bank","prompt":"Policy permits aggregate delivery themes in an approved workspace but excludes recipient addresses. Which two actions support a delivery review?","options":[["a","Upload address-bearing reports and request an aggregate response."],["b","Retain street numbers in a shared Project so Claude can group incidents geographically."],["c","Remove addresses locally and send the minimum excerpts needed to code the themes."],["d","Ask staff to paste reports into private chats in the same workspace."],["e","Confirm with the designated owner that the redacted workflow meets the organization’s policy."]]}', '{"correct":["c","e"],"explanation":"Minimize inputs before processing and confirm the approved workflow rather than assuming access equals authorization.","rationales":{"a":"The prohibited fields would enter the service.","b":"The retained fields are excluded by policy.","c":"This limits submitted data to the approved task.","d":"A private chat does not override the data restriction.","e":"It checks the actual proposed use and input."}}'),
  ('associate-foundations', 1, 'returns-export', 'returns-export', '2026-07.v1', 7, 1, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"Harbor Outfitters","prompt":"A return summary deteriorates after the export replaces the status ‘Returned’ with code R. No other intentional changes went out. What test would give the clearest evidence?","options":[["a","Run matched rows from both export formats through the same setup."],["b","Replace the model and revise the prompt before the next live run."],["c","Use only the newest rows and ask Claude if it understands them."],["d","Make longer summaries and compare the number of mentions of returns."]]}', '{"correct":["a"],"explanation":"Hold the prompt and model fixed while comparing the old and new representations.","rationales":{"a":"It isolates the changed encoding.","b":"Two changes obscure the cause.","c":"A self-report is weaker than a controlled check against expected results.","d":"The number of mentions does not establish which records were handled correctly."}}'),
  ('associate-foundations', 1, 'garden-refund-date', 'garden-refund-date', '2026-07.v1', 2, 3, 'https://platform.claude.com/docs/en/test-and-evaluate/strengthen-guardrails/reduce-hallucinations', '{"scenario":"Riverside Garden Society","prompt":"Claude drafts a refund reply citing June 12. The source says June 12 for volunteers and June 18 for paying members. The sender is a paying member. What should the reviewer change?","options":[["a","Keep June 12 because the date appears in the linked source."],["b","List both dates and tell the sender to pick the one that sounds right."],["c","Use June 18 and cite the paying-member rule."],["d","Use the later date only if a fresh Claude chat returns it independently."]]}', '{"correct":["c"],"explanation":"Check which group the cited rule applies to before sending the reply.","rationales":{"a":"The rule applies to a different group.","b":"The reviewer already knows which group applies.","c":"The claim and its evidence match the sender.","d":"The approved policy is the authoritative check."}}'),
  ('associate-foundations', 1, 'recital-access', 'recital-access', '2026-07.v1', 2, 4, 'https://platform.claude.com/docs/en/test-and-evaluate/strengthen-guardrails/reduce-hallucinations', '{"scenario":"Riverside Arts Council","prompt":"An approved venue memo says a side entrance is step-free. A staff message reports it is blocked today and gives no confirmed alternative. The attendee asks where to enter tonight. What should happen before sending directions?","options":[["a","Verify tonight’s accessible entrance with venue staff and keep that detail pending until confirmed."],["b","Send the side-entrance directions and cite the approved memo."],["c","Send a public map link and say the entrance nearest the street should be accessible."],["d","Forward both notes and let the attendee judge which route works."]]}', '{"correct":["a"],"explanation":"The current report calls the approved route into question. Ask the venue owner for a confirmed route.","rationales":{"a":"The current route needs authoritative operational verification.","b":"The memo does not reflect today’s obstruction.","c":"The map does not establish physical access.","d":"The conflicting sources still leave the attendee without verified directions."}}');
