  ('developer-foundations', 1, 'vendor-batch-api', 'market-hall', 'workbench', 'Separate live orders and the archive import', 'The vendor archive delays urgent confirmations, and retries are creating duplicate imports.', 'prototype-v1'),
  ('developer-foundations', 1, 'library-workers', 'library', 'workbench', 'Scope workers and their catalog connectors', 'The writer is swamped by raw worker logs and each client implements the same catalog integration differently.', 'prototype-v1'),
  ('developer-foundations', 1, 'repair-desk-safety', 'shop', 'workbench', 'Keep repair tools inside their authority', 'A draft assistant can post changes, and an offline supplier is shown as out of stock.', 'prototype-v1'),
  ('developer-foundations', 1, 'developer-release', 'office', 'workbench', 'Release a safer application configuration', 'The new model route passed one hand-picked run. Staff need a credible release gate and prompt rollback.', 'prototype-v1'),
  ('developer-foundations', 1, 'supplier-invoices', 'restaurant', 'original', 'Validate supplier invoices', 'Keep incorrect invoice totals out of the ledger without losing what the supplier printed.', 'prototype-v1');
