insert into certcity_private.item_revisions (track_id, release_no, item_id, family_id, blueprint_version, domain_no, objective_no, source_url, prompt, rubric) values
  ('developer-foundations', 1, 'permit-loop', 'permit-loop', '2026-07.v1', 1, 2, 'https://platform.claude.com/docs/en/build-with-claude/handling-stop-reasons', '{"scenario":"Permit intake","prompt":"A Messages API response has a text preamble and two client tool calls. Its stop reason is tool_use. Both lookups are independent. What should the harness append before its next request?","options":[["a","The text preamble and a user message containing both lookup results as prose."],["b","Two tool results in separate assistant turns, followed by the original request."],["c","The assistant tool calls, then a user turn with both linked tool_result blocks."],["d","One tool result with both lookups under the first ID, then a fresh conversation."]]}', '{"correct":["c"],"explanation":"Preserve the assistant turn and return the corresponding tool results with their IDs so the model can use the observations.","rationales":{"a":"The linkage to the tool-use blocks is lost.","b":"Tool results belong in a user-role message and must follow the tool-use turn.","c":"This matches the client-tool message sequence.","d":"The second tool request is left unmatched and context is discarded."}}'),
  ('developer-foundations', 1, 'shift-deadlines', 'shift-deadlines', '2026-07.v1', 2, 3, 'https://platform.claude.com/docs/en/build-with-claude/batch-processing', '{"scenario":"Market Hall invoices","prompt":"The same extractor serves two queues. A cashier needs confirmation within six seconds. The second queue holds 9,000 archived invoices due tomorrow; all are independent and need no client tool callback. Which split fits?","options":[["a","Use one Message Batch for both queues and poll more often for the cashier’s invoice."],["b","Use live requests for both and put the archive behind the cashier’s requests in the same work queue."],["c","Stream every request and keep the client connected until the full archive completes."],["d","Send the cashier through live Messages and submit the archive as a batch correlated by custom_id."]]}', '{"correct":["d"],"explanation":"Interactive deadlines require live requests. Independent work with an overnight deadline can run through Message Batches with stable IDs.","rationales":{"a":"Polling does not make asynchronous completion meet six seconds.","b":"This can work, but gives up asynchronous batch processing and couples loads unnecessarily.","c":"Streaming improves time to first output for a request, not bulk job scheduling.","d":"Each workload gets a delivery mechanism matching its deadline."}}'),
  ('developer-foundations', 1, 'cutover', 'cutover', '2026-07.v1', 2, 2, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"Dispatch support assistant","prompt":"A replacement prompt matches the average accuracy of the current prompt but drops on address corrections. The release team wants rapid rollback without redeploying application code. Which release control fits?","options":[["a","Overwrite the active prompt and keep the prior version in a ticket in case of failure."],["b","Pin both prompts, test address corrections separately, and switch versions with a flag."],["c","Deploy the candidate everywhere because the aggregate score held, then compare ticket volume."],["d","Pin the model and roll the whole application back if there are enough complaints."]]}', '{"correct":["b"],"explanation":"Deploy versioned configuration behind a reversible switch and define a targeted promotion gate.","rationales":{"a":"Restoring by hand is slower and less reliable than a version switch.","b":"The slice catches the known regression and the flag supports rollback.","c":"Aggregate accuracy masks the known failure group.","d":"That couples prompt rollback to unrelated code."}}'),
  ('developer-foundations', 1, 'test-rules', 'test-rules', '2026-07.v1', 3, 1, 'https://code.claude.com/docs/en/memory', '{"scenario":"Northline monorepo","prompt":"The integration-test convention applies only to files under tests/integration and must be shared. The team wants Claude Code to load it when editing relevant files without crowding unrelated contexts. Where should it go?","options":[["a","A tracked .claude/rules file with paths matching tests/integration."],["b","The root CLAUDE.md, below a heading named Integration Tests."],["c","Each developer’s user-level CLAUDE.md with an integration-test example."],["d","A user-invoked Skill that developers must run before every test edit."]]}', '{"correct":["a"],"explanation":"Project rules with a path selector keep the convention shared and scoped.","rationales":{"a":"This makes the instruction conditional on the relevant path.","b":"A heading does not make instructions load conditionally.","c":"This is personal configuration and can diverge across the team.","d":"Manual invocation does not meet the automatic-loading requirement."}}'),
  ('developer-foundations', 1, 'wire-versus-render', 'wire-versus-render', '2026-07.v1', 4, 1, 'https://platform.claude.com/docs/en/build-with-claude/streaming', '{"scenario":"Market Hall invoice console","prompt":"The SDK’s accumulated final response contains the full JSON and end_turn. The browser shows an incomplete amount when a network buffer splits one event. The backend receipt matches the invoice. Where should the developer test first?","options":[["a","Increase max_tokens and compare the number of characters Claude returns."],["b","Replay a fragmented event in the browser and compare it with the SDK’s final message."],["c","Rewrite the extraction prompt to put amounts first in the response."],["d","Run the same prompt on a larger model and compare browser output."]]}', '{"correct":["b"],"explanation":"The successful accumulated message localizes the observed truncation to forwarding or parsing after the SDK.","rationales":{"a":"The complete final message rules out a model output limit in the observed run.","b":"It reproduces the boundary that differs from the known-good trace.","c":"Ordering does not repair fragmented event handling.","d":"That adds variation without isolating the failing layer."}}'),
  ('developer-foundations', 1, 'prefix-misses', 'prefix-misses', '2026-07.v1', 5, 4, 'https://platform.claude.com/docs/en/build-with-claude/prompt-caching', '{"scenario":"Catering quote intake","prompt":"Every request uses the same 18-page handbook, but prepends the new quote and a current timestamp. Cache reads are zero. The handbook is long enough to qualify. Which change should increase hits?","options":[["a","Put the cache breakpoint at the end of the quote so the whole prompt can be reused."],["b","Round timestamps to the hour and keep quotes before the handbook."],["c","Place stable instructions and the handbook before the breakpoint, then append the timestamp and quote."],["d","Cache each completed quote response in the client under the handbook revision."]]}', '{"correct":["c"],"explanation":"Caching reuses matching prefixes. Put stable content first and keep per-request data after the cached prefix.","rationales":{"a":"The unique quote still breaks the prefix.","b":"The changing quote still precedes the handbook.","c":"Requests can share the same prefix and vary later.","d":"Distinct quotes need distinct answers. This does not fix API cache reuse."}}'),
  ('developer-foundations', 1, 'reconcile-totals', 'reconcile-totals', '2026-07.v1', 6, 3, 'https://platform.claude.com/docs/en/build-with-claude/structured-outputs', '{"scenario":"Juniper Kitchen","prompt":"A schema-valid invoice says total_cents is 12,900, but the only two lines are 4,000 and 7,900 and there are no taxes or fees. The system must preserve what the vendor printed. What should the application do?","options":[["a","Post the invoice because the total and lines are valid integer fields."],["b","Replace the stated total with 11,900 before posting."],["c","Ask Claude to emit a confidence score and post if it reports high confidence."],["d","Record the stated and computed amounts, flag the mismatch, and send the invoice to review."]]}', '{"correct":["d"],"explanation":"Check semantic invariants after parsing and preserve the claimed total alongside the discrepancy.","rationales":{"a":"Schema validity does not establish arithmetic agreement.","b":"This silently changes the supplier’s stated amount.","c":"Confidence cannot resolve an observed discrepancy.","d":"It protects the source record and prevents an unsafe posting."}}'),
  ('developer-foundations', 1, 'approval-gate', 'approval-gate', '2026-07.v1', 7, 2, 'https://platform.claude.com/docs/en/test-and-evaluate/strengthen-guardrails/mitigate-jailbreaks', '{"scenario":"Community Center booking","prompt":"A helper can draft and cancel bookings. Policy requires staff to approve each cancellation. The staff portal and an overnight job both use the same booking service. Which two controls enforce that rule?","options":[["a","Put the rule in the portal’s system prompt and audit cancellations nightly."],["b","Verify the caller and a matching, unconsumed approval at the cancellation endpoint."],["c","Allow the job to use a service account that bypasses approval and restrict its schedule."],["d","Require portal approval only for cancellations proposed by Claude."],["e","Give the drafting workflow only draft permissions until an authorized write path is invoked."]]}', '{"correct":["b","e"],"explanation":"Apply the approval gate where the action occurs and keep each caller’s permissions narrowly scoped.","rationales":{"a":"This misses the overnight path and acts after the cancellation.","b":"Both paths must pass the same gate before state changes.","c":"The service account would provide another unapproved path.","d":"The scenario requires approval regardless of the proposer.","e":"A draft workflow cannot write with the same credential."}}'),
  ('developer-foundations', 1, 'repair-contract', 'repair-contract', '2026-07.v1', 8, 1, 'https://modelcontextprotocol.io/specification/2026-07-28/server/tools', '{"scenario":"Sam’s Repair Shop","prompt":"A parts tool can complete with no stock or fail because the supplier inventory is offline. Staff need to tell those outcomes apart and may retry an offline read once. Which MCP result design fits?","options":[["a","Return empty stock as a successful result and offline as isError with a retryable category."],["b","Return isError on both outcomes with separate human-readable messages."],["c","Return empty successful results for both and place offline details in logs."],["d","Return the same JSON-RPC unknown-tool error for both and have the caller retry once."]]}', '{"correct":["a"],"explanation":"Reserve the execution-error flag for the unavailable source and use app-defined recovery data.","rationales":{"a":"Consumers can distinguish no stock from a search that failed.","b":"The completed empty lookup is a valid result.","c":"The calling assistant receives the same data for two different states.","d":"The call reached a valid tool and one of the outcomes needs no retry."}}'),
  ('developer-foundations', 1, 'before-write', 'before-write', '2026-07.v1', 1, 2, 'https://code.claude.com/docs/en/hooks', '{"scenario":"City records indexing","prompt":"A workflow can delete outdated index entries. Validation must block deletion when a replacement snapshot is missing. The team wants a deterministic SDK hook. Where should it run?","options":[["a","In a hook after the deletion tool returns, with a warning for failed validation."],["b","At session start, taking one snapshot of replacement status."],["c","After the user prompt is submitted, looking for the word delete."],["d","In PreToolUse for the deletion tool, verifying replacement state and denying the call when missing."]]}', '{"correct":["d"],"explanation":"The check must run before the irreversible action and be able to deny the tool call.","rationales":{"a":"A warning after the fact cannot block the deletion.","b":"The state can change between session start and the actual call.","c":"The model may issue the tool call without a matching user phrase.","d":"The check runs at the action boundary before side effects."}}'),
  ('developer-foundations', 1, 'async-join', 'async-join', '2026-07.v1', 2, 4, 'https://platform.claude.com/docs/en/build-with-claude/batch-processing', '{"scenario":"Washington Printworks","prompt":"A batch processes independent proof descriptions. Results can arrive in any order and some fail. The importer must preserve already completed proofs across retries. Which plan fits?","options":[["a","Sort requests by submission time and assign results in the order returned."],["b","Correlate by custom_id, upsert successes, and retry failed requests selectively."],["c","Retry the full batch and append every returned result as a new proof record."],["d","Match results by model-generated proof title, then retry unmatched titles."]]}', '{"correct":["b"],"explanation":"Use stable identifiers to correlate independent outcomes, and make repeated imports safe.","rationales":{"a":"Result ordering is not the correlation contract.","b":"Stable keys and idempotent writes preserve previously completed work.","c":"This produces duplicates and reruns successful requests.","d":"Titles may be duplicated, changed, or absent."}}'),
  ('developer-foundations', 1, 'pin-config', 'pin-config', '2026-07.v1', 2, 6, 'https://code.claude.com/docs/en/settings', '{"scenario":"Northline release tooling","prompt":"Last week’s investigation used a different Claude Code model pin, team settings, and review instructions. The team needs to reproduce that run. Which artifacts should accompany its trace?","options":[["a","The current settings and the old terminal output."],["b","The model family and the date of the release."],["c","The commit, exact model ID, settings revision and prompt version."],["d","The prompt only, because the rest is inferred from the project name."]]}', '{"correct":["c"],"explanation":"Record the versions of the inputs that can change behavior, alongside the run and commit identifiers.","rationales":{"a":"Current settings may not match the run being reproduced.","b":"A family and date cannot recover exact review and settings revisions.","c":"This captures the changeable configuration tied to the trace.","d":"Several relevant environment settings are unspecified."}}'),
  ('developer-foundations', 1, 'request-budget', 'request-budget', '2026-07.v1', 5, 4, 'https://platform.claude.com/docs/en/build-with-claude/token-counting', '{"scenario":"Regional permits importer","prompt":"An importer must reject requests above an input-token budget before model generation. A 1 MB cap misclassifies scans and text. What control should replace the byte estimate?","options":[["a","Count the planned request’s tokens with the Claude token-counting endpoint."],["b","Set max_tokens to the input budget."],["c","Set a maximum number of characters based on one short text example."],["d","Measure usage from the completed response and reject excess after it returns."]]}', '{"correct":["a"],"explanation":"Measure the model input using the token-counting operation with the actual messages and relevant request structure.","rationales":{"a":"It estimates the relevant context size before generation.","b":"That parameter limits generated output.","c":"Character ratios vary by content and do not cover all modalities.","d":"The generation would already have happened."}}'),
  ('developer-foundations', 1, 'empty-versus-bad-id', 'empty-versus-bad-id', '2026-07.v1', 6, 2, 'https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/overview', '{"scenario":"Library intake","prompt":"A prompt performs well on clear form fields but confuses a blank membership number with an unreadable number. The team can add two examples and keep the schema. Which examples have the highest diagnostic value?","options":[["a","Two typical forms with legible membership numbers in different fonts."],["b","A blank date and an unreadable address with no model outputs attached."],["c","Matched blank and unreadable numbers with the expected output for each."],["d","Two successful complete extracts with longer explanations of field formatting."]]}', '{"correct":["c"],"explanation":"Use contrasting examples at the decision boundary, with the desired representation for each.","rationales":{"a":"Both examples demonstrate a case the model already handles.","b":"The field and desired output boundary are left unspecified.","c":"This makes the distinction observable while holding other details stable.","d":"They do not demonstrate the difference between blank and unreadable."}}'),
  ('developer-foundations', 1, 'service-credentials', 'service-credentials', '2026-07.v1', 7, 4, 'https://platform.claude.com/docs/en/api/overview#authentication', '{"scenario":"Northline internal tools","prompt":"A browser-facing app calls a backend that uses Claude. Users sign in individually, and staging must be revocable without affecting production. Which credential arrangement fits?","options":[["a","Embed one restricted API key in the browser and validate the app user on the backend."],["b","Separate the server keys by environment and authorize each user action."],["c","Use one server key everywhere and separate logs by a client-supplied environment label."],["d","Require each user to submit a provider API key into the browser for storage."]]}', '{"correct":["b"],"explanation":"Keep provider credentials server-side, use distinct credentials for the environments, and authorize app users independently.","rationales":{"a":"Browser delivery exposes the provider credential, and it is shared across environments.","b":"Revocation can be scoped while caller permissions are enforced.","c":"Logs cannot isolate access or revocation.","d":"This exposes user credentials and does not implement the app’s own authorization."}}'),
  ('developer-foundations', 1, 'resources-or-tools', 'resources-or-tools', '2026-07.v1', 8, 2, 'https://modelcontextprotocol.io/specification/2026-07-28/server/resources', '{"scenario":"Lucas Branch Library","prompt":"The team wants an MCP client to read a stable policy document by URI and lets the model request a live catalog search. Which capabilities match the two operations?","options":[["a","Expose both as prompts with a document parameter."],["b","Expose both as resources and make each search query a fixed URI."],["c","Expose the policy as a tool and the live search as a prompt."],["d","Expose the policy as a resource and the parameterized catalog search as a tool."]]}', '{"correct":["d"],"explanation":"An addressable document fits a resource. A model-callable lookup with parameters fits a tool.","rationales":{"a":"Prompts are reusable interaction templates, not the needed read and action interfaces.","b":"This does not provide the required model-callable operation as a tool.","c":"That reverses the required direct document access and invocation interfaces.","d":"The client can fetch the document by URI and the model can invoke search."}}'),
  ('developer-foundations', 1, 'fixed-intake', 'fixed-intake', '2026-07.v1', 1, 1, 'https://www.anthropic.com/research/building-effective-agents', '{"scenario":"City permit desk","prompt":"Every submission needs the same two validations in a fixed order. If both pass, Claude drafts an acknowledgment. What control flow should the developer implement first?","options":[["a","Let an agent choose whether each validation is needed from the form content."],["b","Run both validations in application code, then call Claude to draft when they pass."],["c","Ask one model call to validate and draft, returning a confidence score."],["d","Launch one agent per validation and accept whenever either approves."]]}', '{"correct":["b"],"explanation":"Keep known sequencing in a workflow and use the model only for the task that benefits from generation.","rationales":{"a":"Both validations are mandatory.","b":"This implements the required ordering and isolates the generative step.","c":"A self-report does not enforce the two checks.","d":"The rule requires both checks in order."}}'),
  ('developer-foundations', 1, 'worker-history', 'worker-history', '2026-07.v1', 1, 3, 'https://code.claude.com/docs/en/agent-sdk/subagents', '{"scenario":"Regional archive","prompt":"A researcher needs independent review of 50 permit records and 50 map records. Each produces lengthy logs; the final writer only needs cited findings and gaps. How should the developer handle worker context?","options":[["a","Append all raw worker logs to the writer’s conversation."],["b","Use one long worker transcript and strip every source ID from its result."],["c","Return only one confidence value per worker."],["d","Isolate workers’ source sets and return cited findings with coverage gaps."]]}', '{"correct":["d"],"explanation":"Use isolated worker context for the bulk evidence and return compact structured summaries with provenance.","rationales":{"a":"Most of that context does not serve the final synthesis.","b":"That prevents provenance checks.","c":"The writer cannot distinguish claims or coverage gaps.","d":"The synthesis receives actionable evidence without unnecessary logs."}}'),
  ('developer-foundations', 1, 'acceptance-budget', 'acceptance-budget', '2026-07.v1', 2, 1, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"Juniper Kitchen","prompt":"The owner needs the invoice screen to acknowledge input in two seconds. Staff can wait overnight for reconciliation. A finance rule forbids posting unreconciled totals. What should the developer specify before building?","options":[["a","Set separate timing targets and block the posting of unreconciled records."],["b","Require all reconciliation to finish in two seconds."],["c","Use average API time as the acceptance criterion."],["d","Build one synchronous chain and ask finance to check totals after posting."]]}', '{"correct":["a"],"explanation":"Turn the business constraints into acceptance requirements for each stage and enforce the posting invariant.","rationales":{"a":"Each requirement becomes independently testable.","b":"That makes the slower stage meet an unnecessary deadline.","c":"It does not prove acknowledgment or the posting rule.","d":"It ignores both decoupled timing and the preposting requirement."}}'),
  ('developer-foundations', 1, 'session-per-customer', 'session-per-customer', '2026-07.v1', 2, 5, 'https://platform.claude.com/docs/en/claude_api_primer', '{"scenario":"City Dispatch","prompt":"Two operators use the same app and Claude API backend. Their case histories may contain different customers’ notes. Each can resume authorized cases. What session design supports this?","options":[["a","Store the latest turns in one shared history and ask Claude to filter on the current customer."],["b","Use one session per operator and append every case they handle."],["c","Store history by case, check access on resume, and include only that case’s authorized context in Messages requests."],["d","Trust a case number from the browser and resume whatever history it names."]]}', '{"correct":["c"],"explanation":"Load history for the verified case and caller, with a separate session boundary for each case.","rationales":{"a":"The mixed notes already enter model context.","b":"A later case can inherit a different customer’s notes.","c":"This matches both resumption and data isolation.","d":"A case number is not authorization."}}'),
  ('developer-foundations', 1, 'repeatable-regression', 'repeatable-regression', '2026-07.v1', 5, 1, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"Market Hall inbox","prompt":"A classifier gives different labels on repeated runs with identical input. A release gate currently reruns just one record. Which change gives better regression evidence?","options":[["a","Pick whichever run has the most confident wording."],["b","Record a single expected transcript and compare all future outputs byte for byte."],["c","Lower the output limit until runs agree, then count that as accuracy."],["d","Compare repeated trials on a labeled set using pinned settings."]]}', '{"correct":["d"],"explanation":"Evaluate against a representative labeled set with repeated trials where output varies.","rationales":{"a":"Wording does not establish correctness.","b":"Equivalent valid outputs can differ and the test covers only one record.","c":"Agreement can result from truncation and need not match labels.","d":"This captures variability and actual correctness."}}'),
  ('developer-foundations', 1, 'browser-live-status', 'browser-live-status', '2026-07.v1', 5, 2, 'https://platform.claude.com/docs/en/build-with-claude/streaming', '{"scenario":"Northline help desk","prompt":"A browser needs incremental assistant text, but its protocol is fixed to WebSocket for application events. The official Claude SDK runs on the backend and returns a stream. Where should the translation happen?","options":[["a","Send browser WebSocket frames directly to the Messages endpoint."],["b","Translate the backend SDK stream into authenticated WebSocket events."],["c","Expose the provider key so the browser can open its own SDK stream."],["d","Buffer the complete response and send one browser event."]]}', '{"correct":["b"],"explanation":"Let the backend SDK handle Claude’s stream and translate validated events to the app’s browser transport.","rationales":{"a":"The browser protocol is not the upstream SDK’s streaming contract.","b":"It separates provider protocol from browser delivery.","c":"It exposes a server credential and does not use the required app channel.","d":"It removes the required incremental updates."}}'),
  ('developer-foundations', 1, 'model-fallback-slice', 'model-fallback-slice', '2026-07.v1', 5, 3, 'https://platform.claude.com/docs/en/models/overview', '{"scenario":"Transit requests","prompt":"Model A passes the cost and latency targets for routine classifications but misses ambiguous cases. Model B meets the ambiguous quality threshold, but running it for all cases exceeds budget. The app has a validated ambiguity signal. What design should the developer test?","options":[["a","Route flagged cases to B and routine cases to A. Track cost and missed flags."],["b","Run B for all traffic and estimate savings from shorter prompts."],["c","Run A for all cases and route by its prose confidence."],["d","Alternate by request number and rely on overall accuracy."]]}', '{"correct":["a"],"explanation":"Use the validated signal for selective routing and compare both slices against cost and quality targets.","rationales":{"a":"It uses the measured strengths while checking routing errors.","b":"The measured budget fails and the savings are unverified.","c":"A validated signal is available and self-reported confidence may miss cases.","d":"The variant would not reliably reach the difficult cases."}}'),
  ('developer-foundations', 1, 'history-projection', 'history-projection', '2026-07.v1', 6, 1, 'https://www.anthropic.com/research/effective-context-engineering-for-ai-agents', '{"scenario":"City Dispatch","prompt":"Each lookup returns a 400-line history, but later decisions use only the case status and timestamp. Over long sessions Claude repeats old actions. What context change should be tested?","options":[["a","Keep all tool outputs and add a system instruction to ignore old lines."],["b","Remove every timestamp and send only raw status text."],["c","Send current status, timestamp and source ID. Store the full history outside context."],["d","Periodically clear all history without restoring confirmed case state."]]}', '{"correct":["c"],"explanation":"Provide a compact projection for model context while preserving source records and current state elsewhere.","rationales":{"a":"The excessive history remains in context.","b":"Recency is one of the needed fields.","c":"This cuts noise and preserves auditability.","d":"Useful confirmed state can be lost."}}'),
  ('developer-foundations', 1, 'untrusted-attachment', 'untrusted-attachment', '2026-07.v1', 7, 1, 'https://platform.claude.com/docs/en/test-and-evaluate/strengthen-guardrails/mitigate-jailbreaks', '{"scenario":"Supplier intake","prompt":"The app summarizes third-party PDFs and can propose email drafts. Policy allows source documents to contribute facts, and only signed-in staff may send. Which two controls address the trust boundary?","options":[["a","Label and isolate PDF text as untrusted source content when sending it to Claude."],["b","Promote any instructions found in the PDF to system messages."],["c","Let the model decide whether a sender’s job title sounds authorized."],["d","Make the send service verify the staff identity and explicit approval for the draft."],["e","Keep the send service unrestricted and record unauthorized sends for later investigation."]]}', '{"correct":["a","d"],"explanation":"Treat external content as data and enforce send authority in trusted application code.","rationales":{"a":"The prompt can distinguish document evidence from instructions.","b":"An external document does not have application authority.","c":"The app must use verified identity and permissions.","d":"The write is guarded independently of model behavior.","e":"Logging happens after the action."}}'),
  ('developer-foundations', 1, 'scoped-pre-hook', 'scoped-pre-hook', '2026-07.v1', 7, 3, 'https://code.claude.com/docs/en/hooks', '{"scenario":"Northline release assistant","prompt":"A cleanup tool can remove local build files. It must never act outside the selected project directory, including when a path resolves through a link. Where should that policy be checked?","options":[["a","Inspect the tool result afterward and ask the model to restore any wrong deletion."],["b","Validate resolved paths before execution and enforce the same scope in the tool."],["c","Check only whether the path starts with the project’s name as text."],["d","Run a single permission check at session start and trust later inputs."]]}', '{"correct":["b"],"explanation":"Resolve and validate the target before execution, and enforce the same boundary at the tool.","rationales":{"a":"The side effect may already be irreversible.","b":"The control can prevent the action and accounts for path resolution.","c":"A textual prefix does not establish the real filesystem target.","d":"The target is known only at call time."}}'),
  ('developer-foundations', 1, 'procedures-and-live-data', 'procedures-and-live-data', '2026-07.v1', 8, 3, 'https://code.claude.com/docs/en/skills', '{"scenario":"Northline support","prompt":"A team needs a reusable checklist for handling reimbursements and a live lookup that authenticates to a ticket service shared by several clients. How should it extend Claude?","options":[["a","Put the live lookup result for every case into one Skill document."],["b","Use only an MCP resource containing the checklist and let clients guess how to query tickets."],["c","Give each client a copy of the service credential in its instructions."],["d","Use a Skill for the checklist and an authenticated MCP tool for the current ticket lookup."]]}', '{"correct":["d"],"explanation":"Package reusable procedure as a Skill and expose the authenticated live operation as an MCP tool when several clients need it.","rationales":{"a":"A static document cannot provide current authorized results.","b":"The actual lookup capability and reusable procedural workflow are missing.","c":"This creates unnecessary credential exposure and duplication.","d":"Each mechanism matches the capability it supplies."}}'),
  ('developer-foundations', 1, 'parts-stop', 'parts-stop', '2026-07.v1', 1, 2, 'https://platform.claude.com/docs/en/build-with-claude/handling-stop-reasons', '{"scenario":"Harbor bike repair","prompt":"A model returns stop_reason tool_use and a call to a client-side stock lookup. The result has been obtained. What continues the turn correctly?","options":[["a","Start a fresh user prompt containing only the lookup’s output."],["b","Append an assistant message containing the result text."],["c","Wait for end_turn before returning the lookup output."],["d","Append the assistant tool call, then a user tool_result with its ID."]]}', '{"correct":["d"],"explanation":"Return the result immediately after its assistant tool call with the same tool-use ID.","rationales":{"a":"The corresponding tool call would be missing.","b":"The role and content type are incorrect.","c":"The model needs the observation in the next request to continue.","d":"It preserves the required message order and link."}}'),
  ('developer-foundations', 1, 'archive-windows', 'archive-windows', '2026-07.v1', 2, 3, 'https://platform.claude.com/docs/en/build-with-claude/batch-processing', '{"scenario":"Harbor Museums","prompt":"Visitors need interactive item details, while 20,000 archived descriptions can be refreshed overnight. The refresh needs no app tools. Where should you use Message Batches?","options":[["a","Use a batch for visitor requests and run the archive live to keep job accounting simple."],["b","Run visitors through live Messages and correlate asynchronous archive results by ID."],["c","Put both workloads into one batch, assigning visitor requests lower numbered IDs."],["d","Send one streaming request for every archive item within each visitor turn."]]}', '{"correct":["b"],"explanation":"Batch the independent archive requests. Use live Messages for responses with an interactive deadline.","rationales":{"a":"The batch service cannot satisfy an interactive deadline reliably.","b":"The two paths match the latency and independence constraints.","c":"A custom identifier is not a scheduling priority.","d":"This couples a bulk process to individual visitors."}}'),
  ('developer-foundations', 1, 'scoped-conventions', 'scoped-conventions', '2026-07.v1', 3, 1, 'https://code.claude.com/docs/en/memory', '{"scenario":"Bridgeworks repository","prompt":"Only Python migrations need instructions for backward-compatible defaults. The shared rule should apply when Claude Code reads or edits files under db/migrations. What should the team commit?","options":[["a","A developer’s local settings file with a note in a description field."],["b","A global personal instruction for database work."],["c","A .claude/rules file scoped to the migration path."],["d","A root instruction in every project used by the team."]]}', '{"correct":["c"],"explanation":"A path-scoped project rule applies to the relevant files and travels with the repository.","rationales":{"a":"Local settings are personal and the note is not a path rule.","b":"The team would not inherit the instruction and scope is too broad.","c":"This is shared and conditional.","d":"This repeats and broadens a rule that applies to one repository path."}}'),
  ('developer-foundations', 1, 'interrupted-events', 'interrupted-events', '2026-07.v1', 4, 1, 'https://platform.claude.com/docs/en/build-with-claude/streaming', '{"scenario":"Harbor Ferry help desk","prompt":"The application’s captured server trace has a complete message. The UI loses the last two lines only when an event arrives in multiple chunks. What is the first regression test?","options":[["a","Replay fragmented events through the UI decoder against the server message."],["b","Ask Claude for shorter replies and rerun on a live connection."],["c","Increase the API token cap and compare latency."],["d","Test a model fallback only when the server reports max_tokens."]]}', '{"correct":["a"],"explanation":"Replay the transport shape that triggers the bug while keeping the model response fixed.","rationales":{"a":"This isolates framing and accumulation.","b":"It changes input and output without exercising the known failing boundary.","c":"The server already received the full message.","d":"The observed failure is downstream of a completed response."}}'),
  ('developer-foundations', 1, 'manual-prefix', 'manual-prefix', '2026-07.v1', 5, 4, 'https://platform.claude.com/docs/en/build-with-claude/prompt-caching', '{"scenario":"Boatyard assistant","prompt":"A fixed handbook qualifies for prompt caching. Session-specific vessel IDs currently appear before it. Which layout should be tested?","options":[["a","Keep each vessel ID before the handbook and lengthen the cache lifetime."],["b","Move the handbook after the question and add a breakpoint at the end."],["c","Break the handbook into many small requests after the vessel ID."],["d","Put the handbook and stable instructions first, then append the vessel ID and question."]]}', '{"correct":["d"],"explanation":"Reusable content belongs in a stable prefix, before per-request inputs.","rationales":{"a":"A longer lifetime cannot repair a mismatched prefix.","b":"The changing request remains ahead of the cached content.","c":"It preserves the changing prefix and creates extra calls.","d":"Requests can share the common prefix."}}'),
  ('developer-foundations', 1, 'manifest-sum', 'manifest-sum', '2026-07.v1', 6, 3, 'https://platform.claude.com/docs/en/build-with-claude/structured-outputs', '{"scenario":"Pier inventory","prompt":"The model emits valid JSON showing a manifest total of 31 crates, with item counts of 16 and 12. The signed manifest must be preserved. What should the importer do?","options":[["a","Import the declared total because the schema passed."],["b","Store 31 as declared and 28 as calculated, then hold the record for review."],["c","Overwrite 31 with 28 and record a successful import."],["d","Ask for a new extraction with a larger token limit and import any valid JSON."]]}', '{"correct":["b"],"explanation":"Validate relationships among fields and preserve the source assertion until the discrepancy is resolved.","rationales":{"a":"Shape does not establish accuracy.","b":"Both evidence and discrepancy are retained.","c":"This silently changes the source statement.","d":"It may repeat the mismatch or conceal the contradiction."}}'),
  ('developer-foundations', 1, 'publishing-policy', 'publishing-policy', '2026-07.v1', 7, 2, 'https://platform.claude.com/docs/en/test-and-evaluate/strengthen-guardrails/mitigate-jailbreaks', '{"scenario":"Harbor Events","prompt":"A web app and scheduler can publish notices. Every publish needs approval for the exact version. Which two changes make the requirement enforceable?","options":[["a","Verify matching approval and caller authority in the shared publishing service before it writes."],["b","Teach the scheduler the policy in its prompt and let it publish directly."],["c","Give the draft path read and draft access without publish permission."],["d","Allow staff to approve all versions of one notice with a single unchecked flag."],["e","Review a sample of publications each month and reverse unapproved ones."]]}', '{"correct":["a","c"],"explanation":"Enforce approval against the version at the write boundary and limit credentials to their tasks.","rationales":{"a":"Both call paths must satisfy the same check.","b":"The prompt cannot enforce the write requirement.","c":"Draft operations cannot publish with their own credential.","d":"Approval must match the exact version.","e":"A sample is retrospective and may miss violations."}}'),
  ('developer-foundations', 1, 'supplier-outage', 'supplier-outage', '2026-07.v1', 8, 1, 'https://modelcontextprotocol.io/specification/2026-07-28/server/tools', '{"scenario":"Harbor marina store","prompt":"A supply lookup found zero filters for pier A. The supplier for pier B did not respond. A staff client should be able to route each outcome correctly. Which contract supports that?","options":[["a","Return the same success with an empty list and record the outage in server logs."],["b","Return isError for both with one generic availability string."],["c","Return a successful empty list for A and a structured tool error with the retry status for B."],["d","Return a permission error for B so the client avoids a second call."]]}', '{"correct":["c"],"explanation":"A completed empty lookup and an execution failure carry different evidence.","rationales":{"a":"The caller cannot distinguish the two.","b":"The successful empty lookup should stay usable as data.","c":"The caller can report the known result and recover the unavailable one.","d":"Authorization did not cause the timeout, and the recovery decision needs accurate metadata."}}'),
  ('developer-foundations', 1, 'venue-credit-sum', 'venue-credit-sum', '2026-07.v1', 6, 3, 'https://platform.claude.com/docs/en/build-with-claude/structured-outputs', '{"scenario":"Festival ticket office","prompt":"A schema-valid record declares a $92 refund. The two refunded items are $36 and $44, with no adjustment lines. Accounting must preserve the signed request. What should the posting service do?","options":[["a","Post $92 because the schema verified the amount’s type."],["b","Keep the $92 claim and the $80 calculation, and hold the refund for review."],["c","Post $80 and keep the $92 figure only in temporary debug output."],["d","Retry extraction and accept the first schema-valid result."]]}', '{"correct":["b"],"explanation":"Check the relationship between amounts after parsing and retain the signed claim.","rationales":{"a":"The schema does not establish whether the values reconcile.","b":"It records the mismatch and preserves the original.","c":"The discrepancy needs review before posting.","d":"Another schema-valid record can preserve or hide the same discrepancy."}}');
