insert into public.mission_revisions (track_id, release_no, mission_id, place_id, kind, title, brief, engine_version) values
  ('architect-foundations', 1, 'dispatch-lookup', 'dispatch', 'dispatch', 'Repair the order lookup', 'Customers are getting ‘order not found’ replies during supplier timeouts.', 'prototype-v1'),
  ('architect-foundations', 1, 'library-search', 'olive-library', 'workbench', 'Reopen the reference desk', 'The reference assistant stops before returning evidence. Its draft exhibit labels also mix up archive records and photo descriptions.', 'prototype-v1'),
  ('architect-foundations', 1, 'printworks-rules', 'washington-printworks', 'workbench', 'Standardize proof releases', 'Two shifts run the same release differently. Their proof instructions live in personal files, and paper-size rules appear while editing billing code.', 'prototype-v1'),
  ('architect-foundations', 1, 'kitchen-extract', 'restaurant', 'workbench', 'Catch bad supplier invoices', 'The ledger received a valid JSON invoice with an unsupported total. Lina wants to keep the original figures and stop reviewing every easy invoice by hand.', 'prototype-v1'),
  ('architect-foundations', 1, 'community-handoff', 'community', 'workbench', 'Fix room-booking handoffs', 'The booking assistant proposes changes before checking caller eligibility and sends staff a chat transcript with no case summary.', 'prototype-v1'),
  ('architect-foundations', 1, 'archive-coordination', 'library', 'workbench', 'Recover a partial archive search', 'The city wants a sourced exhibit brief today. Two specialists duplicated the map search and a third source never replied.', 'prototype-v1'),
  ('architect-foundations', 1, 'release-review', 'office', 'workbench', 'Review the order-system migration', 'Northline is migrating a shared order identifier. A small label fix is ready, but the identifier’s downstream dependencies are unclear.', 'prototype-v1'),
  ('architect-foundations', 1, 'repair-shop-tools', 'shop', 'workbench', 'Give the repair desk the right tools', 'Sam’s assistant can edit jobs when it only needs a status check. The shared connector also disappears on a fresh workstation.', 'prototype-v1'),
  ('architect-foundations', 1, 'printworks-ci', 'washington-printworks', 'workbench', 'Make review useful at the release gate', 'The review job can stall without a terminal. It flags allowed print tolerances and missed a mismatch between the renderer and the order format.', 'prototype-v1'),
  ('architect-foundations', 1, 'market-close', 'market-hall', 'workbench', 'Keep vendor records reliable at closing', 'Market staff need instant confirmations and an overnight summary. The last run lost delivery dates and approved wrong handwritten totals with high confidence.', 'prototype-v1'),
  ('architect-foundations', 1, 'dispatch-monday-peak', 'dispatch', 'workbench', 'Keep the peak shift within capacity', 'A supplier outage hits the depot during a busy shift. Staff have two hours for follow-up and the lookup budget is $3.20.', 'prototype-v1'),
  ('architect-foundations', 1, 'market-rush', 'market-hall', 'workbench', 'Run the vendor rush without missing a deadline', 'Inez added a counter service. The team has 60 minutes to review invoices and a $1.60 processing budget for the rush.', 'prototype-v1');
