insert into certcity_private.item_revisions (track_id, release_no, item_id, family_id, blueprint_version, domain_no, objective_no, source_url, prompt, rubric) values
  ('architect-foundations', 1, 'lost-item-loop', 'lost-item-loop', '2026-07.v1', 1, 1, 'https://platform.claude.com/docs/en/build-with-claude/handling-stop-reasons', '{"scenario":"Transit lost property","prompt":"Claude returns a sentence saying it will check a locker and a tool_use block. After the lookup, the next response ends with end_turn. Where should the harness finish?","options":[["a","Finish after the first text block, and record the lookup as a background task."],["b","Execute the lookup, append the linked result, and finish when the next response ends the turn."],["c","Finish after one successful lookup without another model call."],["d","Continue after end_turn until the model sends an empty response."]]}', '{"correct":["b"],"explanation":"The preamble does not end the turn. Execute the pending call, send its result, and finish at end_turn.","rationales":{"a":"The model still needs the lookup result.","b":"This respects both stop reasons and completes the request.","c":"The lookup has not yet been interpreted for the user.","d":"End turn is already the normal completion signal."}}'),
  ('architect-foundations', 1, 'archive-missing-slice', 'archive-missing-slice', '2026-07.v1', 1, 2, 'https://www.anthropic.com/engineering/multi-agent-research-system', '{"scenario":"Lucas Branch Library","prompt":"A coordinator assigned one worker to permits and another to maps. Permits are complete. Maps returned district coverage with one missing ward. The final answer needs all wards. What should the coordinator do?","options":[["a","Restart both workers with a shared history and hope the map gap is noticed."],["b","Ask the map worker to write the whole answer from its own context."],["c","Send a targeted map follow-up for the missing ward, then synthesize both workers’ evidence."],["d","Synthesize now and infer the missing ward from nearby wards."]]}', '{"correct":["c"],"explanation":"Keep validated work and delegate only the uncovered slice with an explicit completion criterion.","rationales":{"a":"The verified work is repeated and responsibility for the gap is vague.","b":"It lacks the permit worker’s evidence.","c":"This fills the gap without rerunning successful work.","d":"The coverage requirement needs evidence for that ward."}}'),
  ('architect-foundations', 1, 'two-workers', 'two-workers', '2026-07.v1', 1, 3, 'https://code.claude.com/docs/en/agent-sdk/subagents', '{"scenario":"Rail maintenance archive","prompt":"A coordinator already knows the equipment ID and date range. Two separate agents must inspect independent manuals, and each may use only its assigned collection. Which two changes make the invocation reliable?","options":[["a","Include the equipment ID, dates and expected citations in each worker’s prompt."],["b","Omit the equipment ID so each worker infers it from the coordinator’s transcript."],["c","Give both workers all connector tools so they can discover the other collection if needed."],["d","Launch the independent calls together with each worker restricted to its assigned collection."],["e","Run both tasks in the same worker history and alternate which collection is named."]]}', '{"correct":["a","d"],"explanation":"Workers need explicit task facts and a scoped capability surface. Independent calls can start together.","rationales":{"a":"Isolated workers need the relevant facts and deliverable explicitly.","b":"Delegated contexts do not automatically include the coordinator’s full transcript.","c":"It violates the collection boundary.","d":"Parallel dispatch saves time and preserves scope.","e":"It mixes otherwise isolated work and weakens the data boundary."}}'),
  ('architect-foundations', 1, 'refund-order', 'refund-order', '2026-07.v1', 1, 4, 'https://www.anthropic.com/research/building-effective-agents', '{"scenario":"Market Hall returns","prompt":"A return assistant can check receipts and submit refunds. Service policy requires account verification before every refund. A refund call could arrive from a resumed conversation. What change enforces the ordering?","options":[["a","Require matching verification in the refund service before it accepts the write."],["b","Start every system prompt with ‘verify before refunds’."],["c","Check verification in a post-refund hook and alert the supervisor."],["d","Accept the conversation summary’s statement that the account was verified."]]}', '{"correct":["a"],"explanation":"Bind verified account state to the refund attempt and enforce it at the write boundary.","rationales":{"a":"The gate applies even after resumption or a different call path.","b":"The prompt is guidance rather than enforcement.","c":"The refund has already happened.","d":"A summary can be stale or inaccurate."}}'),
  ('architect-foundations', 1, 'two-hooks', 'two-hooks', '2026-07.v1', 1, 5, 'https://code.claude.com/docs/en/hooks', '{"scenario":"Market Hall booking assistant","prompt":"The team wants to block a publish call before it changes bookings and convert successful lookup timestamps into ISO strings before Claude reads them. Where do these checks belong?","options":[["a","Use PostToolUse for both checks and roll back unauthorized publishes."],["b","Gate publish in PreToolUse and normalize the lookup response in PostToolUse."],["c","Use PreToolUse for both and transform the not-yet-returned response there."],["d","Set both as prompt instructions and inspect the next assistant turn."]]}', '{"correct":["b"],"explanation":"Authorization belongs before execution. Response normalization belongs after a successful lookup.","rationales":{"a":"The write would already occur before the check.","b":"Each check runs at the point where it can accomplish its purpose.","c":"The lookup response does not exist before execution.","d":"Prompt instructions do not deterministically intercept the call or transform the result."}}'),
  ('architect-foundations', 1, 'old-payment-module', 'old-payment-module', '2026-07.v1', 1, 6, 'https://www.anthropic.com/research/building-effective-agents', '{"scenario":"Northline release room","prompt":"A team knows the three stages of an invoice migration, but dependencies in one undocumented billing module are unknown. The release review must detect local defects and cross-module contract breaks. How should work be decomposed?","options":[["a","Fix every subtask before inspecting the undocumented module and review each file in isolation."],["b","Give one unrestricted task the entire migration and request a longer final report."],["c","Keep known stages, investigate dependencies, then review local and cross-module behavior."],["d","Ask three workers to propose independent migrations and select the longest proposal."]]}', '{"correct":["c"],"explanation":"Use known stages as the scaffold, allow discovery where dependencies are unknown, and reserve a pass for integration.","rationales":{"a":"Unknown dependencies can invalidate the plan, and local review misses integration.","b":"It leaves dependency discovery and cross-module checks implicit.","c":"The workflow adapts where facts are missing and checks both defect classes.","d":"Proposal length does not test dependency coverage or contract correctness."}}'),
  ('architect-foundations', 1, 'branch-investigation', 'branch-investigation', '2026-07.v1', 1, 7, 'https://code.claude.com/docs/en/sessions', '{"scenario":"Northline incident investigation","prompt":"An investigation has a verified baseline and unchanged source files. The team wants to test two repair strategies independently while preserving the baseline session. Which workflow fits?","options":[["a","Resume the baseline and try both strategies in sequence in the same conversation."],["b","Start two empty conversations and ask each to rediscover the baseline."],["c","Compact the original conversation before each strategy and keep writing in it."],["d","Fork each alternative from the same saved session and isolate any working-tree changes."]]}', '{"correct":["d"],"explanation":"Fork from the known baseline for each branch so alternatives do not rewrite the original or contaminate each other.","rationales":{"a":"The second strategy inherits decisions and assumptions from the first.","b":"That can work, but discards verified context and repeats work.","c":"Compaction does not create independent branches.","d":"The baseline remains reusable and experiments stay independent."}}'),
  ('architect-foundations', 1, 'lookup-and-book', 'lookup-and-book', '2026-07.v1', 2, 1, 'https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools', '{"scenario":"Sam’s Repair Shop","prompt":"The tools check_service and service_status have overlapping descriptions. The second creates a booking, and the assistant sometimes chooses it for stock checks. What should the developer change first?","options":[["a","Rename both tools with longer names but keep the same descriptions."],["b","Clarify the read and write descriptions, then retest ambiguous requests."],["c","Keep both definitions and ask users to include the exact tool name in their request."],["d","Force the booking tool whenever the request includes the word service."]]}', '{"correct":["b"],"explanation":"Clarify capability boundaries in names and descriptions, including the side effect and examples of when each tool applies.","rationales":{"a":"The model still receives overlapping instructions about when to use them.","b":"The tool boundary and change in behavior are observable.","c":"This pushes ambiguity to users and leaves tool routing brittle.","d":"Ordinary lookup questions can contain the same word."}}'),
  ('architect-foundations', 1, 'two-failure-layers', 'two-failure-layers', '2026-07.v1', 2, 2, 'https://modelcontextprotocol.io/specification/2026-07-28/server/tools', '{"scenario":"Market Hall inventory","prompt":"The stock tool returns a completed empty result for freezer A and isError with an offline category for freezer B. The client then loses its MCP connection while checking freezer C and receives no result. How should the report distinguish the three?","options":[["a","Say A and C are empty because no item records arrived, and B is offline."],["b","Treat all three as tool execution errors and retry them together."],["c","A checked and empty, B unavailable at the tool, C unchecked after disconnect."],["d","Report only B because it is the sole result containing an error payload."]]}', '{"correct":["c"],"explanation":"Each source has different evidence: verified empty, an execution error, and a transport failure without a tool result.","rationales":{"a":"C never produced a completed lookup.","b":"A succeeded and C returned no tool result.","c":"The report preserves coverage and the observed failure layers.","d":"The completed A result and C coverage gap are both important."}}'),
  ('architect-foundations', 1, 'cross-role-tool', 'cross-role-tool', '2026-07.v1', 2, 3, 'https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools', '{"scenario":"City Dispatch","prompt":"A triage agent needs the status of a specific escalated case, but it should never change a case or see other customers’ records. The supervisor agent already has case-management tools. What should triage receive?","options":[["a","A status-only lookup scoped to the verified case and caller."],["b","The supervisor toolset with a prompt telling triage to call only read methods."],["c","A named forced call to the existing supervisor update tool with an empty body."],["d","A cached export of all escalations so triage can find the row locally."]]}', '{"correct":["a"],"explanation":"Add only the read capability the triage role needs and enforce access on the service side.","rationales":{"a":"It enables the handoff without granting unrelated access.","b":"It grants unnecessary authority and relies on model behavior.","c":"It uses a write-capable interface and does not enforce the record boundary.","d":"It exposes unrelated cases."}}'),
  ('architect-foundations', 1, 'connector-scope', 'connector-scope', '2026-07.v1', 2, 4, 'https://code.claude.com/docs/en/mcp', '{"scenario":"Northline release room","prompt":"Everyone on one repository needs the same shared issue MCP server. A developer is testing a second personal server. Each teammate supplies their own token outside version control. Which two configuration choices fit?","options":[["a","Commit both servers and their tokens so all developer environments match."],["b","Put the shared server in the repository’s .mcp.json with environment-variable references."],["c","Put the shared server in one developer’s personal configuration and document its name."],["d","Put the shared server in a root instruction file and let Claude reconstruct credentials."],["e","Keep the experimental server in a personal or project-local scope."]]}', '{"correct":["b","e"],"explanation":"Keep the team connection in tracked project configuration and use a personal scope for the experiment.","rationales":{"a":"The experiment is personal and tokens must stay out of version control.","b":"This shares the connection definition without committing token values.","c":"Other developers do not inherit that configuration.","d":"Instructions are not the MCP server configuration or a credential store.","e":"Other contributors do not receive the personal experiment."}}'),
  ('architect-foundations', 1, 'exact-edit', 'exact-edit', '2026-07.v1', 2, 5, 'https://code.claude.com/docs/en/cli-reference', '{"scenario":"Washington Printworks repository","prompt":"The team needs to find every TypeScript call to formatReceipt and adjust one known call without replacing its file. The implementation can use built-in search and editing tools. Which combination best fits?","options":[["a","Use Glob to find call text and Write to recreate the modified file."],["b","Use Read on the first TypeScript file and infer other call sites from imports."],["c","Use Write to replace the file and compare all changes after saving."],["d","Search TypeScript file contents with Grep, inspect the target, then apply a targeted Edit."]]}', '{"correct":["d"],"explanation":"Use content search for call sites and a targeted edit for the known occurrence.","rationales":{"a":"Glob matches paths, and rewriting is broader than needed.","b":"One file does not establish repository-wide coverage.","c":"It risks unrelated rewrites and does not locate the call sites.","d":"The tools match the search and minimal-change tasks."}}'),
  ('architect-foundations', 1, 'shared-workspace-rule', 'shared-workspace-rule', '2026-07.v1', 3, 1, 'https://code.claude.com/docs/en/memory', '{"scenario":"Northline platform team","prompt":"A build convention applies to everyone in a repository. One engineer also prefers personal explanation style across projects. How should these instructions be maintained?","options":[["a","Put both rules in the engineer’s user instructions."],["b","Commit both rules in the project instructions."],["c","Use project CLAUDE.md for the convention and user instructions for personal style."],["d","Keep both rules in a previous chat and ask new sessions to refer to it."]]}', '{"correct":["c"],"explanation":"Track shared instructions with the repository and keep individual preferences in user scope.","rationales":{"a":"Teammates will not inherit the build convention.","b":"The personal preference becomes a team rule.","c":"Each instruction reaches the people and projects it is meant to affect.","d":"New sessions do not automatically inherit that conversation."}}'),
  ('architect-foundations', 1, 'publish-skill', 'publish-skill', '2026-07.v1', 3, 2, 'https://code.claude.com/docs/en/skills', '{"scenario":"Washington Printworks","prompt":"A checklist with supporting examples is run on demand before releases by every contributor. It needs a stable invocation and should be versioned with the repository. Which packaging fits?","options":[["a","Add a project Skill with the checklist and linked examples."],["b","Put the complete checklist in each contributor’s user instructions."],["c","Add the examples as a Git ignore rule and paste the checklist into each release chat."],["d","Move the checklist into managed permissions with examples as allow rules."]]}', '{"correct":["a"],"explanation":"A project Skill can provide a named workflow and supporting resources, tracked with the code.","rationales":{"a":"It provides shared versioning and an on-demand entry point.","b":"It is not shared and loads outside this workflow.","c":"Neither mechanism supplies a tracked, named workflow.","d":"Permission rules govern execution, rather than teach a procedure."}}'),
  ('architect-foundations', 1, 'cross-tree-tests', 'cross-tree-tests', '2026-07.v1', 3, 3, 'https://code.claude.com/docs/en/memory', '{"scenario":"Regional library monorepo","prompt":"Database tests live in three packages. A validation rule should apply to matching test files across packages and should be absent when reading application files. What should the team commit?","options":[["a","Repeat the instructions in every package’s general CLAUDE.md."],["b","Place one instruction under the first package’s test directory."],["c","Place a line in the root instructions and ask the assistant to skip it during application work."],["d","Commit one .claude/rules file with paths matching the database test files across all packages."]]}', '{"correct":["d"],"explanation":"Use a path-scoped rule with patterns for all applicable test files.","rationales":{"a":"The rule would apply to application work in those packages too.","b":"Other packages would not be covered.","c":"It still loads globally.","d":"The selector expresses the actual scope without duplicating the rule."}}'),
  ('architect-foundations', 1, 'unknown-impact', 'unknown-impact', '2026-07.v1', 3, 4, 'https://code.claude.com/docs/en/settings', '{"scenario":"Transit ticketing repository","prompt":"One change adjusts a known label in a single component. Another replaces the identifier used by three undocumented services. Which working mode fits the two changes?","options":[["a","Use direct edits for both and discover downstream failures after deployment."],["b","Edit the known label directly, and plan the identifier migration after tracing its dependencies."],["c","Require a full read-only architecture plan for the label and immediately patch the identifier."],["d","Fork both tasks from an unrelated completed session before editing."]]}', '{"correct":["b"],"explanation":"Direct execution suits a clear local edit. Read-oriented planning helps discover dependencies before a broad change.","rationales":{"a":"It skips discovery before the risky identifier migration.","b":"This matches the cost and uncertainty of each request.","c":"The higher-risk task receives less discovery.","d":"Session branching does not answer the dependency or planning question."}}'),
  ('architect-foundations', 1, 'null-fixture', 'null-fixture', '2026-07.v1', 3, 5, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"Northline maintenance bench","prompt":"An import fix corrected valid dates but still crashes on null and misclassifies empty strings. Both cases share the same normalization function. What feedback should the engineer give next?","options":[["a","Ask Claude to improve date handling across the project without examples."],["b","Show the longest production log and ask for a more defensive implementation everywhere."],["c","Provide expected outputs for null and empty strings and test the shared function."],["d","Fix each caller separately without checking their common function."]]}', '{"correct":["c"],"explanation":"Provide concrete failing inputs and expected outputs, then verify the related fixes together.","rationales":{"a":"The failing distinctions are left unspecified.","b":"It broadens the change without specifying the contract.","c":"The examples distinguish the cases and make progress verifiable.","d":"This can duplicate inconsistent handling and leave the underlying defect."}}'),
  ('architect-foundations', 1, 'ci-review', 'ci-review', '2026-07.v1', 3, 6, 'https://code.claude.com/docs/en/cli-reference', '{"scenario":"Washington Printworks CI","prompt":"CI must run a review without a terminal and send typed findings to a consumer. The job will retry on the same commit. Which configuration fits?","options":[["a","Run headless with validated JSON and publish each finding once per commit."],["b","Start an interactive session and scrape its terminal output as JSON."],["c","Run headless with prose output and post each paragraph as a finding."],["d","Use schema output but post findings again every time a retry completes."]]}', '{"correct":["a"],"explanation":"Use noninteractive execution and validate the machine-readable response before publishing. Make publication idempotent.","rationales":{"a":"CI gets a typed result and retries do not duplicate comments.","b":"The process can block and terminal text is not a stable contract.","c":"Prose paragraphs do not meet the typed interface.","d":"The response may be typed, but publication duplicates remain."}}'),
  ('architect-foundations', 1, 'review-criteria', 'review-criteria', '2026-07.v1', 4, 1, 'https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/overview', '{"scenario":"Northline code review","prompt":"An automated reviewer reports undocumented rounding, even when a documented tolerance explicitly allows the behavior. The team wants to retain true defects. What prompt change should it test?","options":[["a","Tell the reviewer to be less strict about rounding everywhere."],["b","Tie findings to the documented tolerance and show examples on both sides."],["c","Require the reviewer to attach a confidence score and drop the lowest quarter."],["d","Increase context and keep the same instructions."]]}', '{"correct":["b"],"explanation":"Define the observable condition for a finding and illustrate both sides of the boundary.","rationales":{"a":"This can suppress real violations as well.","b":"The criterion distinguishes the false positives from genuine defects.","c":"Confidence is not tied to the documented boundary.","d":"More context does not state the missing rule."}}'),
  ('architect-foundations', 1, 'two-edge-examples', 'two-edge-examples', '2026-07.v1', 4, 2, 'https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/overview', '{"scenario":"Juniper Kitchen procurement","prompt":"Invoice extraction works on printed totals but confuses a handwritten ‘pending’ total with a missing total. Only two examples can be added. Which pair is most useful?","options":[["a","Two invoices with clearly printed totals."],["b","One example with many taxes and another with two invoice pages."],["c","Two examples that both omit the total with no target output."],["d","A missing total and a pending total, each with the expected output."]]}', '{"correct":["d"],"explanation":"Matched examples should contrast the specific ambiguous boundary and show the intended output.","rationales":{"a":"They rehearse a case already handled.","b":"They add variation on unrelated dimensions.","c":"They do not distinguish missing from pending.","d":"The pair teaches the exact distinction the model misses."}}'),
  ('architect-foundations', 1, 'schema-and-policy', 'schema-and-policy', '2026-07.v1', 4, 3, 'https://platform.claude.com/docs/en/build-with-claude/structured-outputs', '{"scenario":"Market Hall supplier intake","prompt":"Every shipment record needs a status from a fixed enum and a nullable date. Downstream rules also reject dates earlier than the purchase order. The chosen model supports structured outputs. Which two controls are required?","options":[["a","Require the status enum and nullable date in the output schema."],["b","Add one formatted example and accept any response containing both field names."],["c","Compare the parsed date with the purchase order before accepting the record."],["d","Have Claude report whether the date is plausible and accept a yes response."],["e","Use the output schema alone to validate all purchase-order relationships."]]}', '{"correct":["a","c"],"explanation":"Constrain the output shape and validate the business relationship against trusted order data.","rationales":{"a":"The schema constrains types, required keys and allowed statuses.","b":"Presence alone does not guarantee type or allowed values.","c":"The trusted order supplies a separate semantic constraint.","d":"A model assertion is weaker than a deterministic comparison.","e":"The schema as specified has no trusted order-date input."}}'),
  ('architect-foundations', 1, 'repair-versus-review', 'repair-versus-review', '2026-07.v1', 4, 4, 'https://platform.claude.com/docs/en/build-with-claude/structured-outputs', '{"scenario":"Transit pass reconciliation","prompt":"The verifier finds one date in the wrong format and another invoice with two conflicting stated totals. The original source is available. Which recovery policy fits?","options":[["a","Retry the date with specific format feedback. Send both totals to review."],["b","Retry both original prompts with no details and accept the first valid JSON."],["c","Set every invalid or conflicting field to null and accept the records."],["d","Choose the larger stated total and correct the date in the application before auto-posting."]]}', '{"correct":["a"],"explanation":"Correct a well-specified formatting failure with targeted feedback. Preserve conflicts for adjudication.","rationales":{"a":"Formatting is repairable while the underlying conflict requires a decision.","b":"The model receives no guidance and can hide the conflict in valid output.","c":"This loses two known source values and hides why the record failed.","d":"The larger amount has no stated precedence."}}'),
  ('architect-foundations', 1, 'permit-digest', 'permit-digest', '2026-07.v1', 4, 5, 'https://platform.claude.com/docs/en/build-with-claude/batch-processing', '{"scenario":"City records archive","prompt":"A nightly digest accepts independent summaries, while a pre-merge job must finish within two minutes. A batch run produced 8,990 successes and ten temporary failures. What approach fits?","options":[["a","Batch both workflows and poll the pre-merge result each second."],["b","Run the whole archive live again and overwrite every prior result."],["c","Keep live requests for pre-merge and resubmit only failed digest records using stable IDs."],["d","Hold all successful digests until every failure disappears in a full rerun."]]}', '{"correct":["c"],"explanation":"Batch the tolerant work, retain successful outputs by ID, and handle latency-critical work synchronously.","rationales":{"a":"Polling does not create a guaranteed two-minute completion.","b":"This repeats successful work unnecessarily.","c":"It respects both workloads and preserves completed results.","d":"This creates needless coupling and repeats valid work."}}'),
  ('architect-foundations', 1, 'independent-integration-review', 'independent-integration-review', '2026-07.v1', 4, 6, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"Northline release room","prompt":"The coding session sees its own design rationale and keeps overlooking a mismatch between modules. Local test quality is strong. Which extra review step addresses the evidence?","options":[["a","Ask the coding session to reread the rationale before checking each file."],["b","Run another lint pass on individual files."],["c","Review only changes the author reports as low confidence."],["d","Run an independent pass over the module contracts and integration tests."]]}', '{"correct":["d"],"explanation":"A separate reviewer can inspect cross-module behavior without inheriting the authoring session’s assumptions.","rationales":{"a":"The same framing remains and file-local checks miss interactions.","b":"Lint does not establish that module contracts agree.","c":"Confidence may omit the systematic mismatch.","d":"This targets the gap using independent context and observable evidence."}}'),
  ('architect-foundations', 1, 'exact-dates', 'exact-dates', '2026-07.v1', 5, 1, 'https://www.anthropic.com/research/effective-context-engineering-for-ai-agents', '{"scenario":"City Dispatch","prompt":"A long case contains three distinct orders, each with a confirmed promised date. After compaction Claude applies one date to all orders. What should be carried into later turns?","options":[["a","The last assistant answer, which mentions the most recent promised date."],["b","A verified order-to-date mapping with source IDs and relevant recent turns."],["c","A longer free-text summary without order IDs."],["d","The entire raw conversation in every turn with no record indexing."]]}', '{"correct":["b"],"explanation":"Keep precise issue-level facts in durable structured state and inject the relevant records when needed.","rationales":{"a":"It cannot represent all three order-date links.","b":"It preserves the exact mapping across compaction.","c":"The ambiguity remains even if more words are used.","d":"It adds context and leaves the association vulnerable to recall errors."}}'),
  ('architect-foundations', 1, 'different-escalations', 'different-escalations', '2026-07.v1', 5, 2, 'https://www.anthropic.com/research/building-effective-agents', '{"scenario":"Lucas Community Center","prompt":"Case A explicitly asks for a person after two failed attempts. Case B requests an eligible reservation, but two rooms share the same nickname. Which dispositions fit?","options":[["a","Try another automated resolution for A and escalate B immediately."],["b","Choose the most frequently used room for B and ask A to repeat the request."],["c","Hand A to staff with attempted steps and ask B for a distinguishing room detail."],["d","Send both cases to staff without the attempted steps."]]}', '{"correct":["c"],"explanation":"Honor the direct escalation request and clarify the resolvable ambiguity in the other case.","rationales":{"a":"It ignores the explicit request and skips the useful clarification.","b":"Room popularity is not evidence of intent.","c":"Both responses respect the information and request available.","d":"The handoff loses context and consumes staff time for a tractable ambiguity."}}'),
  ('architect-foundations', 1, 'partial-research', 'partial-research', '2026-07.v1', 5, 3, 'https://www.anthropic.com/engineering/multi-agent-research-system', '{"scenario":"City records research","prompt":"A coordinator receives verified permit findings. A map worker exhausted its one retry and covered only half the districts. The report is due now. What should the worker’s handoff enable?","options":[["a","Replace the entire report with a map outage message."],["b","Return only successful map rows so the coordinator can infer the rest was empty."],["c","Restart the entire research workflow after the deadline."],["d","Return verified results, uncovered districts and the failed retry history."]]}', '{"correct":["d"],"explanation":"Preserve usable results and surface the uncovered scope, attempts, and remaining action.","rationales":{"a":"The verified permit and map findings still have value.","b":"Uncovered districts are not confirmed empty.","c":"The deadline and retry budget are already exhausted.","d":"The reader can distinguish evidence from coverage gaps."}}'),
  ('architect-foundations', 1, 'compaction-index', 'compaction-index', '2026-07.v1', 5, 4, 'https://www.anthropic.com/research/effective-context-engineering-for-ai-agents', '{"scenario":"Northline codebase investigation","prompt":"A cross-package diagnosis spans many files. After compaction the next session must know two verified call paths, one disproven theory, and three files left to inspect. How should the team carry that forward?","options":[["a","Save verified paths, the rejected theory and pending file checks in a scratchpad."],["b","Save the broad task title and rerun discovery from the top."],["c","Capture only the assistant’s confidence in its current theory."],["d","Include every previously read file in a new prompt without a manifest."]]}', '{"correct":["a"],"explanation":"Persist a focused investigation record with durable references and open checks.","rationales":{"a":"The record can be reloaded after context changes.","b":"It loses tested hypotheses and repeats work.","c":"Confidence does not preserve the supporting or contrary evidence.","d":"It makes targeted recovery difficult and consumes context."}}'),
  ('architect-foundations', 1, 'confidence-audit', 'confidence-audit', '2026-07.v1', 5, 5, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"Market Hall invoice review","prompt":"An extractor auto-posts above 0.9 confidence. On handwritten forms it gives many wrong amounts above 0.9. The team can add 100 review slots per week. What should determine routing?","options":[["a","Raise the universal threshold to 0.95 without checking labels."],["b","Allocate slots equally across all fields using the aggregate confidence distribution."],["c","Measure amount errors by form type, route risky cases to review, and audit a sample of accepted results."],["d","Use agreement between two runs as the sole posting rule."]]}', '{"correct":["c"],"explanation":"Calibrate against labeled outcomes by form and field, and audit the supposedly safe population.","rationales":{"a":"A higher threshold may retain the same overconfident errors.","b":"It does not target the known high-risk form and field.","c":"This uses observed error and checks for residual false confidence.","d":"Two runs can share the same error."}}'),
  ('architect-foundations', 1, 'conflicting-estimates', 'conflicting-estimates', '2026-07.v1', 5, 6, 'https://www.anthropic.com/engineering/multi-agent-research-system', '{"scenario":"Neighborhood Council","prompt":"One worker reports 420 visitors from a February sign-in count. Another reports 560 from a March survey estimate. The sources measure different periods and populations. How should the coordinator write the figure?","options":[["a","Average them and present 490 visitors as the best current estimate."],["b","Report each figure with its source, period and method."],["c","Use the newer number and cite both sources as confirmation."],["d","Report a single range of 420–560 without labels."]]}', '{"correct":["b"],"explanation":"Preserve provenance and explain differences in time, scope, and method before making comparisons.","rationales":{"a":"The inputs are not comparable measurements of the same population.","b":"The reader can evaluate why the figures differ.","c":"The earlier source does not confirm the newer estimate.","d":"The range hides meaningful methodological differences."}}'),
  ('architect-foundations', 1, 'meter-tool-turn', 'meter-tool-turn', '2026-07.v1', 1, 1, 'https://platform.claude.com/docs/en/build-with-claude/handling-stop-reasons', '{"scenario":"Harbor utilities","prompt":"A model says ‘checking the meter’ and issues a read tool call with stop_reason tool_use. The tool returns a value. What should the harness do next?","options":[["a","Display the preamble as the final response and log the value."],["b","Replace the assistant turn with a plain-text result and start over."],["c","Return the linked tool result and continue the loop within its budget."],["d","Wait for end_turn from the current response before sending the result."]]}', '{"correct":["c"],"explanation":"A tool-use stop pauses generation for the external observation. Resume with the linked result.","rationales":{"a":"The user still needs the interpretation of the reading.","b":"The tool-use link and original context are discarded.","c":"The harness feeds back the observation and respects completion signals.","d":"The call must be answered in a subsequent request."}}'),
  ('architect-foundations', 1, 'completed-or-disconnected', 'completed-or-disconnected', '2026-07.v1', 2, 2, 'https://modelcontextprotocol.io/specification/2026-07-28/server/tools', '{"scenario":"Coastal equipment exchange","prompt":"One search completed with zero matches. A second call reached the tool but its supplier service was unavailable. A third lost its MCP connection before any result. Which report can a coordinator defend?","options":[["a","First checked and empty, second tool failed, third disconnected before a result."],["b","All three had zero matches and can be retried if staff disagree."],["c","All three are protocol errors because no inventory items were returned."],["d","The first two were checked and empty, and the third was denied."]]}', '{"correct":["a"],"explanation":"Only the completed search establishes absence. Preserve both failure layers for recovery.","rationales":{"a":"The report retains what is known and where each failure occurred.","b":"Two calls never established an empty inventory.","c":"An empty successful search and a tool execution error are not protocol errors.","d":"Neither a supplier failure nor transport loss establishes those outcomes."}}'),
  ('architect-foundations', 1, 'scope-receipts', 'scope-receipts', '2026-07.v1', 3, 3, 'https://code.claude.com/docs/en/memory', '{"scenario":"Harbor ferry monorepo","prompt":"A receipt test rule must load for matching test files in two service directories, without adding context to feature files. Which setup fits?","options":[["a","Place a copy in root and give it a heading identifying receipt tests."],["b","Set the rule in a team member’s personal instructions."],["c","Store it in the first service’s test directory only."],["d","Track a rule with paths covering receipt tests in both directories."]]}', '{"correct":["d"],"explanation":"Path-specific repository rules can match files across separate directory trees.","rationales":{"a":"The heading does not scope loading.","b":"It will neither be shared nor limited to the target files.","c":"The other service would not receive it.","d":"Its selector covers the needed cases and leaves feature files alone."}}'),
  ('architect-foundations', 1, 'membership-shape', 'membership-shape', '2026-07.v1', 4, 3, 'https://platform.claude.com/docs/en/build-with-claude/structured-outputs', '{"scenario":"Harbor Rowing Club","prompt":"A structured output must contain a membership type and a nullable expiration date. Some plans require an expiration according to a separate club registry. Which two checks belong in the pipeline?","options":[["a","Allow free-form text and check that it mentions a type and date."],["b","Define the allowed type values and the nullable date in the response schema."],["c","Accept any schema-valid null date without looking up the plan."],["d","Ask the model to say whether its own date follows the registry."],["e","Validate the parsed date requirement against the authoritative registry entry before saving."]]}', '{"correct":["b","e"],"explanation":"Use the schema for response shape and registry rules for eligibility of the resulting value.","rationales":{"a":"This does not enforce the allowed values or null type.","b":"This constrains the returned fields.","c":"Some plans explicitly require an expiration.","d":"A self-report does not check the authoritative rules.","e":"This applies the business rule using the proper source."}}'),
  ('architect-foundations', 1, 'coverage-shift', 'coverage-shift', '2026-07.v1', 5, 3, 'https://www.anthropic.com/engineering/multi-agent-research-system', '{"scenario":"Coastal flood planning","prompt":"One worker verified road closures. Another exhausted its retry for two of five tide stations. How should the coordinator preserve the evidence at the deadline?","options":[["a","Say every station was checked and list only the three returned readings."],["b","Discard road closures because the station set is incomplete."],["c","Report verified data and identify the two stations unavailable after retry."],["d","Replace the missing readings with last week’s figures as current evidence."]]}', '{"correct":["c"],"explanation":"Synthesize what was verified and carry forward missing coverage with attempted recovery.","rationales":{"a":"It implies coverage that did not happen.","b":"Independent verified findings remain usable.","c":"This distinguishes verified evidence from gaps.","d":"Older readings do not establish the current state."}}'),
  ('architect-foundations', 1, 'peak-human-request', 'peak-human-request', '2026-07.v1', 5, 2, 'https://www.anthropic.com/research/building-effective-agents', '{"scenario":"Harbor equipment rentals","prompt":"A renter asks to speak with a person after a pickup mismatch. Another renter wants a refund but two contracts share the same surname. The tool can search by a contract number the second renter has. Which handling plan fits?","options":[["a","Send both renters a contract-number request and wait before offering staff."],["b","Transfer the first renter with the attempted steps and ask the second for the contract number."],["c","Transfer both after asking each renter to repeat the full history."],["d","Choose the newest contract for the second renter and transfer the first without the attempted steps."]]}', '{"correct":["b"],"explanation":"Honor the explicit human request. Use a targeted clarification when the other case can still be disambiguated safely.","rationales":{"a":"The first renter already asked for a person.","b":"This preserves the handoff and resolves ambiguity before acting.","c":"The first renter should not have to repeat available context, and the second can supply one distinguishing fact.","d":"Recency does not identify the contract and staff lose the useful history."}}'),
  ('architect-foundations', 1, 'rush-scheduling', 'rush-scheduling', '2026-07.v1', 4, 5, 'https://platform.claude.com/docs/en/build-with-claude/batch-processing', '{"scenario":"Apartment maintenance service","prompt":"A resident portal has a two-second acknowledgment deadline. A separate overnight run classifies 2,000 archived work orders with no external tool callbacks. Last night three jobs failed and result order varied. Which plan fits?","options":[["a","Use a live request for the resident’s acknowledgment."],["b","Poll the same batch for the resident’s acknowledgment and archive results."],["c","Batch archive records, join by custom_id, and resubmit only retryable failures."],["d","Resubmit the full archive batch and replace records in return order."],["e","Put the archives in the portal’s live queue at opening."]]}', '{"correct":["a","c"],"explanation":"Keep deadline-bound work on the interactive path. Correlate and retry independent batch records by stable ID.","rationales":{"a":"The interactive path can be tested against the acknowledgment deadline.","b":"A batch does not provide the required interactive completion bound.","c":"Stable IDs preserve successful work despite result reordering.","d":"Successful work is repeated and return order is not a reliable key.","e":"The approach creates competition with the deadline-bound workload."}}'),
  ('architect-foundations', 1, 'rush-case-state', 'rush-case-state', '2026-07.v1', 5, 1, 'https://www.anthropic.com/research/effective-context-engineering-for-ai-agents', '{"scenario":"Community legal intake","prompt":"A session tracks two unrelated appointments for one participant. One was verified for Tuesday and the other for Thursday. After context compaction, both show Thursday. What state should subsequent turns receive?","options":[["a","The last confirmation text, together with the participant’s name."],["b","A participant-level summary stating there are two appointments."],["c","All raw turns appended under a single date heading."],["d","Verified appointment IDs, dates, and source references for the active issue."]]}', '{"correct":["d"],"explanation":"Durable exact facts need identifiers and source links, so compaction does not merge separate events.","rationales":{"a":"One confirmation cannot recover two distinct appointment dates.","b":"The date-to-appointment associations remain missing.","c":"The representation obscures the separate verified facts.","d":"Each date stays tied to the right record and can be checked."}}'),
  ('architect-foundations', 1, 'rush-review-slice', 'rush-review-slice', '2026-07.v1', 5, 5, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"Regional insurance intake","prompt":"An extractor’s overall accuracy is 97%. On faint scanned forms it misreads a covered amount in 8 of 40 high-confidence records. The review team can check 50 records a day. What is the most defensible next policy?","options":[["a","Raise the confidence threshold globally and spend all review slots on the lowest scores."],["b","Use the 97% result to keep auto-processing and investigate monthly complaints."],["c","Route faint scans for amount review and sample accepted records by source type."],["d","Accept high-confidence results whenever two identical configurations agree."]]}', '{"correct":["c"],"explanation":"Use labeled outcomes for the affected field and source type. Keep a sample of accepted cases to detect residual errors.","rationales":{"a":"The observed mistakes occur at high confidence in a particular slice.","b":"Aggregate accuracy masks the field-level error and complaints are delayed.","c":"Review capacity targets the observed failures while audits monitor remaining risk.","d":"Agreement can reproduce the same systematic error."}}');
