insert into public.mission_revisions (track_id, release_no, mission_id, place_id, kind, title, brief, engine_version) values
  ('architect-professional', 1, 'public-permit-discovery', 'old-courthouse', 'workbench', 'Design a permit support pilot', 'The sponsor wants a chatbot. Staff spend most of their time asking applicants for missing attachments.', 'prototype-v1'),
  ('architect-professional', 1, 'library-retrieval-architecture', 'olive-library', 'workbench', 'Modernize the archive search', 'The archive’s retrieval misses accession numbers and separates procedures from revision headers.', 'prototype-v1'),
  ('architect-professional', 1, 'professional-eval-gate', 'office', 'workbench', 'Build the pilot’s evaluation gate', 'A candidate improves handle time but fails more disputed and uncommon requests.', 'prototype-v1'),
  ('architect-professional', 1, 'market-scale', 'market-hall', 'workbench', 'Control context and inference cost', 'A multi-team vendor service is exceeding its token budget. Similar cases also need consistent treatment.', 'prototype-v1'),
  ('architect-professional', 1, 'tenant-tools', 'shop', 'workbench', 'Share a service without sharing customer records', 'Three assistants need a common lookup. Current agents receive every tool, including tools for unrelated records and writes.', 'prototype-v1'),
  ('architect-professional', 1, 'community-controls', 'community', 'workbench', 'Put approval and privacy controls into production', 'Draft recommendations are useful, but disputed actions need staff decisions and the diagnostic pipeline retains too much.', 'prototype-v1'),
  ('architect-professional', 1, 'regional-operations', 'office', 'workbench', 'Hand the service to operations', 'The implementation team is leaving. An outage must route work manually in ten minutes, and different teams need consistent release practices.', 'prototype-v1'),
  ('architect-professional', 1, 'support-pilot', 'office', 'original', 'Plan the support rollout', 'Pick a pilot that meets the service, spending, and dispute-handling requirements.', 'prototype-v1');
