insert into certcity_private.item_revisions (track_id, release_no, item_id, family_id, blueprint_version, domain_no, objective_no, source_url, prompt, rubric) values
  ('architect-professional', 1, 'split-authority', 'split-authority', '2026-07.v1', 1, 3, 'https://www.anthropic.com/research/building-effective-agents', '{"scenario":"Northline Systems","prompt":"A support assistant must classify every ticket, search approved manuals for unusual cases, and let an authorized reviewer approve all account changes. Classification and review routes are fixed. Which architecture fits?","options":[["a","Give one general agent all capabilities and instruct it to seek approval for account changes."],["b","Build an exhaustive branching workflow that enumerates every manual and query."],["c","Use a fixed classification and approval workflow, with a bounded read-only search component for unusual cases."],["d","Use one retrieval call for all tickets and let staff inspect account changes in a daily report."]]}', '{"correct":["c"],"explanation":"Use a predictable outer workflow with a bounded search component where the path genuinely varies.","rationales":{"a":"The approval boundary depends on the agent following instructions.","b":"Unusual cases have varying retrieval paths and would be costly to enumerate.","c":"This keeps required controls deterministic while allowing variable search.","d":"A retrospective report cannot meet the pre-change approval requirement."}}'),
  ('architect-professional', 1, 'model-envelope', 'model-envelope', '2026-07.v1', 2, 1, 'https://platform.claude.com/docs/en/models/overview', '{"scenario":"City records migration","prompt":"On a representative set, model A scores 95% at $0.01 per case and p95 1.6 s. Model B scores 98% at $0.04 and p95 2.8 s. The accepted targets are at least 94%, at most $0.02, and p95 below 2 s. Which configuration should enter a controlled rollout?","options":[["a","Use A as the candidate and monitor the same measures on a controlled rollout."],["b","Use B for all traffic because its accuracy exceeds A by three points."],["c","Use A and B on every request, accepting the answer when they agree."],["d","Randomly route half of cases to B because the median response is likely fast enough."]]}', '{"correct":["a"],"explanation":"A satisfies all three observed thresholds. Preserve slice-level monitoring during rollout.","rationales":{"a":"It meets the measured quality, cost and latency targets.","b":"B exceeds both the cost and latency limits.","c":"This adds cost and waits for B without demonstrating any quality gain.","d":"This does not establish the tail-latency and cost requirements."}}'),
  ('architect-professional', 1, 'part-number-index', 'part-number-index', '2026-07.v1', 3, 6, 'https://www.anthropic.com/research/contextual-retrieval', '{"scenario":"Regional maintenance network","prompt":"Queries mix exact part numbers such as HZ-847B and descriptions such as ‘seal for a cold-water valve’. Dense retrieval alone misses rare IDs. What retrieval change should the team test first?","options":[["a","Raise the number of dense candidates and keep ranking them only by embedding similarity."],["b","Replace semantic search with phrase matching for all queries."],["c","Concatenate the first pages of all manuals into the system prompt."],["d","Combine lexical and semantic candidates, rerank them, and measure exact-ID and descriptive recall separately."]]}', '{"correct":["d"],"explanation":"Combine lexical matching for rare identifiers with semantic retrieval for descriptive queries. Evaluate both slices.","rationales":{"a":"This may recover some IDs at additional cost, but still lacks a dedicated exact-match signal.","b":"That can recover IDs but loses synonyms and paraphrases.","c":"This increases context and may omit the relevant sections.","d":"It supports both query shapes and makes regressions observable."}}'),
  ('architect-professional', 1, 'canary-slices', 'canary-slices', '2026-07.v1', 4, 3, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"Northline support rollout","prompt":"A new prompt reduces average handle time by 18%. A labeled set shows worse answers on escalated cases. The team can expose 5% of eligible tickets to the candidate. Which release experiment is defensible?","options":[["a","Route the candidate to the fastest region and compare it to last month’s global average."],["b","Randomize eligible cases, gate on escalation quality and latency, and stop if the slice threshold fails."],["c","Route only easy cases to the candidate and use aggregate handle time as the release gate."],["d","Roll out to every user, adding manual review only if total complaints rise."]]}', '{"correct":["b"],"explanation":"Compare variants on comparable traffic, track high-risk slices separately, and predefine rollback.","rationales":{"a":"Region and time can confound the comparison.","b":"This tests incremental effect and protects the known weak segment.","c":"The experiment would not test the observed problem.","d":"The safety signal can be diluted, and exposure is larger than required."}}'),
  ('architect-professional', 1, 'review-payout', 'review-payout', '2026-07.v1', 5, 3, 'https://platform.claude.com/docs/en/test-and-evaluate/strengthen-guardrails/mitigate-jailbreaks', '{"scenario":"Regional reimbursement desk","prompt":"A model drafts payment recommendations. Policy demands a human decision on disputed source evidence and a trace of the actual approved payment. Which two controls meet those requirements?","options":[["a","Route cases with contradictory source evidence to a reviewer with both documents and the proposed amount."],["b","Allow high-confidence disputed recommendations to proceed, then show them in a monthly audit."],["c","Record only a reviewer’s final approve button click, without the amount or record version."],["d","Record reviewer identity and approved amount against the exact version, and enforce that binding before payment."],["e","Send disputed cases to a second model and pay automatically when both agree."]]}', '{"correct":["a","d"],"explanation":"Require adjudication of discrepancies and bind the downstream action to the reviewed version.","rationales":{"a":"The reviewer has the evidence needed to adjudicate the disagreement.","b":"Retrospective audit cannot supply the required decision before the action.","c":"The log cannot establish which action was authorized.","d":"This makes the executed action traceable to the approval.","e":"Agreement does not satisfy the human decision requirement."}}'),
  ('architect-professional', 1, 'service-objectives', 'service-objectives', '2026-07.v1', 6, 3, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"Northline Systems","prompt":"Operations wants fast answers. Compliance requires no automatic closure of disputed tickets. Finance has a per-resolution cap. What should be agreed before a pilot?","options":[["a","Use total tickets closed as the common measure and negotiate thresholds after launch."],["b","Agree on a median response target and let each department monitor its own success independently."],["c","Agree on latency and cost targets, a zero-auto-closure guardrail for disputed tickets, and a named rollback owner."],["d","Pilot the most capable model and use staff sentiment to decide whether the limits are appropriate."]]}', '{"correct":["c"],"explanation":"Translate each requirement into a measurable acceptance condition and specify who acts when a condition fails.","rationales":{"a":"Throughput omits both prohibited closures and cost per resolution.","b":"There is no joint release rule or owner for conflicting signals.","c":"It gives each stakeholder an observable condition and a response plan.","d":"Sentiment does not measure the stated constraints."}}'),
  ('architect-professional', 1, 'team-controls', 'team-controls', '2026-07.v1', 7, 1, 'https://code.claude.com/docs/en/settings', '{"scenario":"Northline engineering","prompt":"Three teams need the same code-review workflow. A company-wide restriction on production writes must apply even if a repository changes its configuration. Which placement is appropriate?","options":[["a","Put workflow and restriction in each user’s personal instructions."],["b","Put both in the workflow Skill’s prose."],["c","Place the restriction in an untracked local file and commit the workflow to each repository."],["d","Share a review Skill and enforce production access through centrally managed controls."]]}', '{"correct":["d"],"explanation":"Share the workflow as maintained project content and enforce the organization-wide restriction at a managed boundary.","rationales":{"a":"Personal settings are inconsistent and do not enforce a company-wide policy.","b":"Instructions in an optional workflow cannot enforce production access.","c":"The tracked workflow is shareable, but the local restriction can drift or be omitted.","d":"This matches the different scope and enforcement needs."}}'),
  ('architect-professional', 1, 'case-packet', 'case-packet', '2026-07.v1', 1, 2, 'https://code.claude.com/docs/en/agent-sdk/subagents', '{"scenario":"Lucas Branch Library","prompt":"Specialist workers classify documents for a resident request. A worker may see only its assigned source collection. The coordinator needs disagreements preserved before producing a consolidated answer. Which handoff fits?","options":[["a","Give workers a shared history and ask them to ignore collections outside their specialty."],["b","Give each worker scoped sources and return claim IDs, provenance and unresolved conflicts to the coordinator."],["c","Let each worker produce an anonymous confidence score and take the weighted mean."],["d","Send all source texts to each worker and deduplicate their final answers centrally."]]}', '{"correct":["b"],"explanation":"Scope inputs to each worker and require evidence-rich results so disagreements survive aggregation.","rationales":{"a":"A prompt does not enforce the data boundary.","b":"This preserves least privilege and supports auditable synthesis.","c":"Scores do not preserve underlying evidence or disagreement.","d":"Deduplication comes after the prohibited exposure."}}'),
  ('architect-professional', 1, 'tenant-boundary', 'tenant-boundary', '2026-07.v1', 3, 2, 'https://platform.claude.com/docs/en/test-and-evaluate/strengthen-guardrails/mitigate-jailbreaks', '{"scenario":"Multi-tenant policy assistant","prompt":"An MCP search endpoint holds policy snippets from multiple organizations. Users sign in to the application. A shared search service identity can read the full index. Where should tenant access be enforced?","options":[["a","Derive tenant scope from verified identity and enforce it in search."],["b","Retrieve globally, then ask Claude to keep only snippets marked with the current tenant."],["c","Let the browser send a tenant label and trust it if the user is signed in."],["d","Use separate client prompts for tenants and share the unrestricted search tool."]]}', '{"correct":["a"],"explanation":"The trusted retrieval path must derive scope from authenticated identity and filter every query before returning content.","rationales":{"a":"This puts scope enforcement at the data access boundary.","b":"Unauthorized content would already reach the model.","c":"Authentication alone does not prove access to the supplied tenant.","d":"Prompt separation does not restrict backend access."}}'),
  ('architect-professional', 1, 'cache-regression', 'cache-regression', '2026-07.v1', 4, 5, 'https://platform.claude.com/docs/en/build-with-claude/prompt-caching', '{"scenario":"Regional service desk","prompt":"A release leaves output length and model fixed. Input-token spend rises and cache reads fall when new ticket IDs start appearing before an unchanged instruction prefix. What should the team compare?","options":[["a","Compare only median wall-clock latency before and after the release."],["b","Reduce output limits and compare total token cost after the next deployment."],["c","Move the ticket ID around the breakpoint in matched requests and compare cache usage."],["d","Switch providers and treat any reduction in spend as proof of the cache hypothesis."]]}', '{"correct":["c"],"explanation":"The layout change offers a concrete cache hypothesis. Compare request structure and usage counters with all other inputs held steady.","rationales":{"a":"Latency can change for multiple reasons and does not isolate cache behavior.","b":"Output limits do not explain fewer cache reads with unchanged output size.","c":"This tests the causal change and tracks the relevant billing quantities.","d":"Provider changes can change price and performance independently of caching."}}'),
  ('architect-professional', 1, 'runbook-owner', 'runbook-owner', '2026-07.v1', 6, 5, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"City Dispatch service launch","prompt":"The implementation team hands the assistant to operations. A vendor outage must trigger manual handling within ten minutes, and review quality is tracked weekly. Which handoff makes that operable?","options":[["a","Provide a sequence diagram and ask operations to raise a ticket whenever complaints rise."],["b","Send a dashboard URL and assign all incidents to the model vendor."],["c","Train staff to turn the assistant off if needed and keep quality reviews with the implementation team indefinitely."],["d","Deliver alerts and a tested manual-routing runbook, assign an on-call owner, and schedule review of labeled cases."]]}', '{"correct":["d"],"explanation":"Turn service commitments into triggers with owners, procedures, recovery criteria and quality review.","rationales":{"a":"The diagram supplies no trigger or guaranteed response for the outage target.","b":"A vendor may repair service but cannot operate the local manual queue.","c":"The trigger, ownership and recovery criteria are still unspecified.","d":"This supports both the ten-minute response and the recurring quality obligation."}}'),
  ('architect-professional', 1, 'minimum-exposure', 'minimum-exposure', '2026-07.v1', 3, 8, 'https://www.anthropic.com/research/effective-context-engineering-for-ai-agents', '{"scenario":"Regional grants operations","prompt":"A helper starts each turn with 70 tool definitions, though each task family uses four. Tool choice errors and input cost have risen. The authorization matrix already exists. Which change should the architect test?","options":[["a","Send all tool definitions and add a separate example for each tool."],["b","Expose a scoped discovery step for authorized capabilities and measure selection errors and input usage by task family."],["c","Rename all tools and increase the input window while exposing the same definitions."],["d","Allow the model to search all capabilities first and apply the authorization matrix only after tool results return."]]}', '{"correct":["b"],"explanation":"Discover relevant capabilities on demand from the authorized surface, then measure tool selection and token cost.","rationales":{"a":"This adds context and does not narrow the choice surface.","b":"It tests whether progressive discovery resolves both problems.","c":"It may help some naming collisions but preserves the full context burden.","d":"Unauthorized definitions and potentially results can be exposed before enforcement."}}'),
  ('architect-professional', 1, 'segment-check', 'segment-check', '2026-07.v1', 5, 5, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"Neighborhood grant intake","prompt":"A draft-screening assistant reports 94% overall agreement with staff. Only 5% of the test cases came from small community groups, and incorrect exclusions have a serious consequence. What evidence should the review board ask for?","options":[["a","Review false exclusions by group on a better represented labeled set and retain staff review of exclusions."],["b","Ask for a higher overall score using more cases sampled from the same mix."],["c","Remove the group field from inputs and treat equal acceptance rates as the only fairness measure."],["d","Compare mean confidence by group and allow automated exclusions where confidence is highest."]]}', '{"correct":["a"],"explanation":"Measure error types on affected groups with enough labeled cases to reveal disparities, and preserve human oversight.","rationales":{"a":"This makes the consequential error visible while keeping decisions reviewable.","b":"The larger groups still dominate the aggregate.","c":"Proxy features can remain, and equal rates do not reveal false exclusions.","d":"Confidence without calibration does not measure the observed error."}}'),
  ('architect-professional', 1, 'release-rubric', 'release-rubric', '2026-07.v1', 7, 2, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"Washington Printworks engineering","prompt":"Claude Code review repeats findings across successive commits and misses interactions across changed modules. The team can add one review pass and retain a record of previous findings. Which change best addresses both?","options":[["a","Ask the original editing session to post the same findings after every commit for traceability."],["b","Suppress all findings in files that already received comments."],["c","Run a separate pass over cross-module behavior and track findings by issue identity and evidence across commits."],["d","Review only changed lines and deduplicate by exact wording."]]}', '{"correct":["c"],"explanation":"Use a focused independent integration pass and deduplicate stable findings across revisions while allowing changed evidence through.","rationales":{"a":"It retains both duplicate noise and the author’s blind spots.","b":"A later commit can add a distinct issue in the same file.","c":"This targets the missed class and preserves new findings without repeating unchanged ones.","d":"Cross-file behavior is missed and paraphrased duplicates persist."}}'),
  ('architect-professional', 1, 'value-hypothesis', 'value-hypothesis', '2026-07.v1', 1, 1, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"Regional permit service","prompt":"Leaders ask for a chatbot to reduce a six-day permit turnaround. Logs show most time is spent waiting for reviewers to request missing attachments. What proposal follows from the evidence?","options":[["a","Launch a general FAQ bot and track the number of chat sessions."],["b","Pilot a completeness check and track incomplete referrals and turnaround."],["c","Automate permit approval and sample files monthly."],["d","Upgrade the model serving the website and compare response latency."]]}', '{"correct":["b"],"explanation":"Tie the intervention to the delay mechanism and retain the legally required review step.","rationales":{"a":"This does not address incomplete applications or turnaround.","b":"This tests a specific cause of delay using outcome measures.","c":"The proposal exceeds the identified need and removes review.","d":"Website response time is not the observed bottleneck."}}'),
  ('architect-professional', 1, 'dispatch-by-query', 'dispatch-by-query', '2026-07.v1', 1, 4, 'https://www.anthropic.com/engineering/multi-agent-research-system', '{"scenario":"Regional utilities","prompt":"Meter questions need one specialist. Outage reports need a network specialist and sometimes a weather specialist. Calling all three for every ticket exceeds budget. What should the coordinator do?","options":[["a","Run all workers concurrently and reduce their output budgets."],["b","Give the meter worker the other tools and make it write every final response."],["c","Run the cheapest worker first and accept its answer whenever it is confident."],["d","Dispatch only relevant specialists, then check coverage before merging."]]}', '{"correct":["d"],"explanation":"Dispatch based on the evidence needed, isolate specialties and fill uncovered scope before final synthesis.","rationales":{"a":"Parallelism can reduce latency but still incurs unnecessary work.","b":"It broadens one worker and couples unrelated tasks.","c":"Confidence does not prove coverage of the requested topic.","d":"This fits the work and controls unnecessary calls."}}'),
  ('architect-professional', 1, 'migration-stages', 'migration-stages', '2026-07.v1', 1, 5, 'https://www.anthropic.com/research/building-effective-agents', '{"scenario":"Regional records migration","prompt":"A migration needs fixed privacy checks, variable mapping across old formats, and an approval before import. A prototype tried all work in one turn and obscured why a file failed. What decomposition supports recovery?","options":[["a","Increase the input budget and keep the single turn."],["b","Run approval in parallel with mapping to save time."],["c","Stage preflight, format mapping and validation, then gate import on approval."],["d","Split each file by length and submit chunks without shared schema or checks."]]}', '{"correct":["c"],"explanation":"Use checkpoints around distinct stages so a failure can be isolated and retried without repeating successful work.","rationales":{"a":"A larger context does not create stage-specific evidence.","b":"Approval would occur before its input is final.","c":"It separates uncertain work from deterministic controls and supports targeted recovery.","d":"Chunking alone leaves document-level controls undefined."}}'),
  ('architect-professional', 1, 'cost-per-resolution', 'cost-per-resolution', '2026-07.v1', 1, 6, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"City Dispatch","prompt":"A fast route costs $0.01 per request but half need another paid attempt at $0.03. A single-step route costs $0.022 and resolves the same cases within SLA. Which financial comparison should be presented?","options":[["a","Compare $0.025 with $0.022 per resolution and show both routes’ service results."],["b","Compare $0.01 with $0.022, because first-call cost is the most consistent figure."],["c","Add $0.03 to every fast-route request and report $0.04 per resolution."],["d","Compare total tokens and leave pricing out of the decision."]]}', '{"correct":["a"],"explanation":"Compare total expected cost per resolved case. The retry route costs $0.025 given the stated outcomes.","rationales":{"a":"This includes rework and compares like outcomes.","b":"The unit omits necessary retries.","c":"Only half incur the retry.","d":"Token volume alone does not give cost per resolution."}}'),
  ('architect-professional', 1, 'untrusted-policy-packet', 'untrusted-policy-packet', '2026-07.v1', 2, 2, 'https://platform.claude.com/docs/en/test-and-evaluate/strengthen-guardrails/mitigate-jailbreaks', '{"scenario":"Policy assistant","prompt":"The assistant receives a controlled system policy and external material that may contain instructions. It can propose account adjustments. What architecture respects the authority boundary?","options":[["a","Include all material in one system prompt so it receives the same priority."],["b","Pass external material as labeled untrusted evidence and reserve behavior rules for the controlled instructions."],["c","Let Claude approve adjustments if retrieved text claims to come from a supervisor."],["d","Verify permissions only during onboarding and treat later model decisions as approved."],["e","Verify caller and action authorization in the account service before any write."]]}', '{"correct":["b","e"],"explanation":"Explicitly separate policy from source material and enforce write authority in trusted code.","rationales":{"a":"External content should not have system authority.","b":"This expresses the intended trust boundary in context.","c":"A claim in source content is not authenticated approval.","d":"Write authority must apply to the actual action.","e":"This enforcement does not depend on the model interpreting the input correctly."}}'),
  ('architect-professional', 1, 'boundary-pairs', 'boundary-pairs', '2026-07.v1', 2, 3, 'https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/overview', '{"scenario":"Regional grant routing","prompt":"A model routes complete applications well but confuses an attachment waived by policy with one missing by mistake. Which use of examples should the architect test?","options":[["a","Show matched waived and missing cases. Test the boundary on new cases."],["b","Give more successful complete applications with full narratives."],["c","Add examples only for the larger application class and report overall accuracy."],["d","Ask the model to reason longer without specifying the waiver condition."]]}', '{"correct":["a"],"explanation":"Use paired examples around the observed ambiguity and measure that segment independently.","rationales":{"a":"It demonstrates the classification distinction and checks transfer.","b":"They do not demonstrate the error boundary.","c":"It may hide the smaller weak segment.","d":"More processing time does not add the missing policy distinction."}}'),
  ('architect-professional', 1, 'turn-budget', 'turn-budget', '2026-07.v1', 2, 4, 'https://www.anthropic.com/research/effective-context-engineering-for-ai-agents', '{"scenario":"Coastal service platform","prompt":"Each conversation accumulates hundreds of raw search rows. Later turns need only verified decisions and a few records for the active claim. Which context policy should scale best?","options":[["a","Expand the window and attach all search output every time."],["b","Drop all old turns whenever usage crosses a threshold."],["c","Persist verified case state and retrieve evidence for the active claim."],["d","Replace the whole conversation with an unverified free-text model summary."]]}', '{"correct":["c"],"explanation":"Persist verified state and retrieve relevant evidence while keeping raw logs available outside the prompt.","rationales":{"a":"This raises cost and preserves irrelevant content.","b":"That can discard verified decisions needed later.","c":"This retains required state and avoids replaying the raw corpus.","d":"The summary can lose exact facts or source links."}}'),
  ('architect-professional', 1, 'reused-prefix', 'reused-prefix', '2026-07.v1', 2, 5, 'https://platform.claude.com/docs/en/build-with-claude/prompt-caching', '{"scenario":"City policy service","prompt":"Twelve internal teams use the same long policy and rubric. Team and query metadata change per request. The platform must update the approved policy centrally. What structure supports maintenance and cache reuse?","options":[["a","Fork the rubric and policy into every team’s prompt."],["b","Put changing metadata first and cache the whole request."],["c","Reuse an old answer whenever the same policy revision appears."],["d","Put versioned policy and rubric before the breakpoint and variable metadata after it."]]}', '{"correct":["d"],"explanation":"Version the reusable policy and rubric together, then keep request-specific inputs after the shared cache breakpoint.","rationales":{"a":"Independent copies drift and fragment the reusable prefix.","b":"The per-request prefix is different.","c":"A common policy does not make questions equivalent.","d":"This aligns ownership and cache layout."}}'),
  ('architect-professional', 1, 'role-tool-matrix', 'role-tool-matrix', '2026-07.v1', 3, 1, 'https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools', '{"scenario":"Northline service integration","prompt":"A read-only incident triage agent can currently see 40 tools, including payroll and account changes. Only four are needed for its cases. Which change should the architect make?","options":[["a","Rename all tools and use a larger model."],["b","Expose only needed read tools and enforce that scope in the service."],["c","Keep all tools and add a warning to risky descriptions."],["d","Hide unused tools from the UI while leaving them in the model’s tool list."]]}', '{"correct":["b"],"explanation":"Reduce the exposed surface to task-relevant capabilities and enforce the same scope in the backend.","rationales":{"a":"It may improve recognition but leaves unnecessary powers available.","b":"It improves selection and removes unnecessary authority.","c":"Descriptions do not enforce permission.","d":"The model still receives them and may call them."}}'),
  ('architect-professional', 1, 'rerank-latency', 'rerank-latency', '2026-07.v1', 3, 3, 'https://www.anthropic.com/research/contextual-retrieval', '{"scenario":"Regional archive","prompt":"Reranking every query improves hard-query recall but raises p95 over the service limit. A validated low-recall signal identifies the hard queries. What integration should be tested?","options":[["a","Rerank when the signal indicates a hard query, and verify recall and p95 on representative traffic."],["b","Enable reranking everywhere and replace p95 with median in reports."],["c","Remove reranking and report retrieval latency alone."],["d","Return more dense candidates for every request and assume the signal is unnecessary."]]}', '{"correct":["a"],"explanation":"Use extra retrieval work where its measured benefit justifies the latency and monitor both segments.","rationales":{"a":"This targets the expensive step while checking system constraints.","b":"The measured service limit still fails.","c":"That hides the known quality gain on hard queries.","d":"Additional candidates can raise latency without reproducing the hard-query gain."}}'),
  ('architect-professional', 1, 'join-the-trace', 'join-the-trace', '2026-07.v1', 3, 4, 'https://platform.claude.com/docs/en/api/errors', '{"scenario":"Municipal support platform","prompt":"Support requests traverse a gateway, Claude and two internal lookup services. Overall p95 rose, but logs cannot tell which stage owns the delay. Full ticket contents may not be logged. What instrumentation fits?","options":[["a","Log complete prompts and every source payload in a shared store."],["b","Collect one aggregate timer at the browser."],["c","Record correlated stage timings, outcomes and request IDs without ticket content."],["d","Sample the last successful response from each worker once a day."]]}', '{"correct":["c"],"explanation":"Correlate stage spans using request identifiers and capture timings and outcomes without logging sensitive content.","rationales":{"a":"This violates the data restriction and still requires correlation.","b":"That gives end-to-end latency but cannot localize the delay.","c":"This makes cross-service delay diagnosable within the logging rule.","d":"Uncorrelated samples cannot identify the delayed request path."}}'),
  ('architect-professional', 1, 'manual-section-headers', 'manual-section-headers', '2026-07.v1', 3, 5, 'https://www.anthropic.com/research/contextual-retrieval', '{"scenario":"Transit maintenance manuals","prompt":"A manual’s numbered procedure only makes sense with its model header and safety note. Current fixed-size chunks split those apart. What indexing change should be evaluated?","options":[["a","Reduce chunk size further and rely on the model to infer missing section titles."],["b","Index only the table of contents and return a manual name."],["c","Make each manual one chunk and insert all matched manuals into every prompt."],["d","Index coherent procedures with their model, revision and prerequisite context."]]}', '{"correct":["d"],"explanation":"Use document structure to keep necessary context with each retrievable unit.","rationales":{"a":"Smaller chunks can further separate prerequisites.","b":"A name does not provide the procedure and note.","c":"This can overwhelm context and reduces targeted retrieval.","d":"This retains the relationships and makes retrieval quality measurable."}}'),
  ('architect-professional', 1, 'connector-across-hosts', 'connector-across-hosts', '2026-07.v1', 3, 7, 'https://modelcontextprotocol.io/specification/2026-07-28/server/tools', '{"scenario":"Regional service catalog","prompt":"Three MCP-capable assistants need the same permissioned inventory lookup. A fixed nightly ETL independently transfers large CSVs through an existing reliable API. Which integration choice fits?","options":[["a","Move both workloads to agent-to-agent conversation for a consistent architecture."],["b","Provide an authorized MCP lookup to the three assistants and keep the nightly ETL on its existing API."],["c","Replace the ETL API with chat prompts containing CSV text."],["d","Build a separate direct integration for every assistant and remove the shared interface."]]}', '{"correct":["b"],"explanation":"Use a reusable model-facing tool where model clients need it. Keep the established deterministic batch interface.","rationales":{"a":"Neither requires delegating open-ended work to a remote agent.","b":"Each path uses an interface suited to its consumer and execution model.","c":"That discards a reliable deterministic path for bulk work.","d":"This duplicates an operation the clients can already consume through MCP."}}'),
  ('architect-professional', 1, 'quality-and-cost-metrics', 'quality-and-cost-metrics', '2026-07.v1', 4, 1, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"Northline support pilot","prompt":"The sponsor asks for a dashboard that shows faster support without masking poor answers or expensive escalation. What should the dashboard report?","options":[["a","Tokens per request and total sessions."],["b","Median latency and the count of positive feedback events."],["c","Labeled accuracy, escalation errors, p95 latency and cost per resolution."],["d","Model confidence and monthly total spend."]]}', '{"correct":["c"],"explanation":"Measure effectiveness, operational experience and risk together, with denominators tied to the workflow.","rationales":{"a":"This omits correctness, timing and actual outcomes.","b":"Median and voluntary feedback can miss costly failures and tail latency.","c":"These measures expose quality, risk, service experience and cost.","d":"Confidence is not validated quality and spend changes with volume."}}'),
  ('architect-professional', 1, 'mixed-graders', 'mixed-graders', '2026-07.v1', 4, 2, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"Regional claim assistant","prompt":"An eval must check required fields, source grounding, and whether staff can act on a proposed handoff. Which design gives the strongest evidence within limited reviewer time?","options":[["a","Use exact checks for fields and calibrated human sampling for grounding and handoffs."],["b","Ask the generating model to approve its own outputs and record one overall score."],["c","Use exact text matching for every handoff and ignore source evidence."],["d","Review only cases with user complaints."]]}', '{"correct":["a"],"explanation":"Use deterministic checks for verifiable structure and calibrated judgment on qualitative or disputed cases.","rationales":{"a":"This matches the grader to the quality signal and preserves edge coverage.","b":"Self-assessment can reproduce the same blind spots.","c":"Correct handoffs can have different phrasing, and evidence still matters.","d":"The set excludes quiet failures and lacks a defined baseline."}}'),
  ('architect-professional', 1, 'isolate-retrieval-failure', 'isolate-retrieval-failure', '2026-07.v1', 4, 4, 'https://www.anthropic.com/research/contextual-retrieval', '{"scenario":"City planning assistant","prompt":"The wrong revision appears in answers after an index rebuild. A captured request already contains only stale excerpts. When supplied the correct excerpt in a controlled test, the same prompt answers correctly. What should the team diagnose first?","options":[["a","Replace the model and compare answer confidence."],["b","Increase generation tokens so citations can be longer."],["c","Tune the response style before replaying any retrieval queries."],["d","Trace a known-current document through ingestion, revision filtering and retrieval."]]}', '{"correct":["d"],"explanation":"The captured evidence and controlled test point to source selection before generation.","rationales":{"a":"The same model answered correctly when given the right input.","b":"Longer citations do not fix stale retrieved material.","c":"The error appears upstream of the response.","d":"This isolates where the stale evidence enters context."}}'),
  ('architect-professional', 1, 'production-drift', 'production-drift', '2026-07.v1', 4, 6, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"Regional maintenance portal","prompt":"Offline evaluation passed. Two months later, attachments from a newly onboarded office have a different layout. Few users report errors. What should live monitoring add?","options":[["a","Monitor only exception counts from the API."],["b","Sample labeled outcomes by layout and alert the owner on quality drift."],["c","Run the original offline dataset more often without adding current inputs."],["d","Treat low complaint volume as proof that current accuracy held."]]}', '{"correct":["b"],"explanation":"Measure quality on representative production slices and tie anomalies to a review and response path.","rationales":{"a":"A well-formed wrong answer may produce no API error.","b":"It can detect silent drift in the new population.","c":"That verifies the baseline but misses new layouts.","d":"Unreported errors are still possible."}}'),
  ('architect-professional', 1, 'separate-read-and-write', 'separate-read-and-write', '2026-07.v1', 5, 1, 'https://platform.claude.com/docs/en/test-and-evaluate/strengthen-guardrails/mitigate-jailbreaks', '{"scenario":"Regional account platform","prompt":"A support agent needs to look up addresses and propose changes. Governance requires the signed-in operator to approve each change, and high-value accounts require a second reviewer. Which guardrail design fits?","options":[["a","Use a single update tool and ask the agent to collect approvals."],["b","Require a confirmation dialog only for the first change in each session."],["c","Use scoped reads and enforce matching reviewer approvals at the write service."],["d","Allow all changes and reconcile approvals from the audit trail nightly."]]}', '{"correct":["c"],"explanation":"Separate read and write authority, and enforce every required reviewer at the action boundary.","rationales":{"a":"The tool can still write without a verified approval record.","b":"Later changes still need approval.","c":"This preserves both the per-change and second-review conditions.","d":"The change occurs before the required control."}}'),
  ('architect-professional', 1, 'silent-availability-risk', 'silent-availability-risk', '2026-07.v1', 5, 2, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"Public facility finder","prompt":"A retrieval outage is currently represented as an empty list. Residents are told a site has no capacity, even when capacity data was never checked. What risk should be captured first?","options":[["a","Track false denials and test separate behavior for empty and unavailable results."],["b","Classify all empty responses as successful and monitor uptime only."],["c","Increase the model’s confidence threshold for all search results."],["d","Treat this primarily as a copy tone problem and shorten replies."]]}', '{"correct":["a"],"explanation":"The system makes a confident claim from absent evidence. The failure needs distinct states, affected-scope measurement, and a safe response.","rationales":{"a":"This identifies the user harm and its trigger.","b":"That retains the conflation that causes incorrect advice.","c":"Confidence cannot recover missing data or reveal its failure layer.","d":"The claim remains factually unsupported."}}'),
  ('architect-professional', 1, 'retention-control', 'retention-control', '2026-07.v1', 5, 4, 'https://trust.anthropic.com/', '{"scenario":"Regional case assistant","prompt":"The approved privacy plan prohibits full case text in diagnostic logs and requires certain case records to be deleted after an agreed period. The team uses an application database, log store and model service. What should the architect require?","options":[["a","Ask the assistant to omit case text from its answer and keep existing logs."],["b","Set a retention job on the application database and assume other processors follow it."],["c","Encrypt all stores and leave retention to team convention."],["d","Map data flows, redact diagnostics and verify retention settings across stores."]]}', '{"correct":["d"],"explanation":"Convert the approved obligations into concrete controls at each storage and transfer point, with verifiable evidence.","rationales":{"a":"Output wording does not control diagnostic collection or retention.","b":"Independent stores and provider settings require separate checks.","c":"Encryption does not implement the required deletion or collection limit.","d":"It addresses the specific obligations throughout the system."}}'),
  ('architect-professional', 1, 'discovery-before-model', 'discovery-before-model', '2026-07.v1', 6, 1, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"Municipal reporting office","prompt":"A sponsor wants automated answers about permit status. Support staff cite slow records updates; policy staff say some status changes cannot be published before approval. What belongs in discovery?","options":[["a","Choose a model and demonstrate the fastest response on synthetic cases."],["b","Map status changes with owners and agree on disclosure rules and success measures."],["c","Ask the sponsor to select a platform and treat staff concerns as implementation details."],["d","Gather requirements only from frequent users and infer policy from old tickets."]]}', '{"correct":["b"],"explanation":"Collect current workflow evidence and resolve ownership and data constraints before selecting the architecture.","rationales":{"a":"The demo cannot establish the publication rule or source freshness.","b":"This discovers the key constraints and gives the pilot an agreed target.","c":"The constraints can materially change the system design.","d":"Past behavior may not express current publication rules."}}'),
  ('architect-professional', 1, 'brief-the-board', 'brief-the-board', '2026-07.v1', 6, 2, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"Regional support pilot","prompt":"A board must decide between a fast pilot with staff review and broader automation. The broader route has higher estimated savings but failed its disputed-case holdout. Which briefing supports the decision?","options":[["a","Lead with estimated savings and leave the holdout in a technical appendix."],["b","Describe every API and tool used without recommending a rollout decision."],["c","Compare measured trade-offs and propose a limited pilot with stop conditions."],["d","Present both variants as equal because the observed cases are only a sample."]]}', '{"correct":["c"],"explanation":"Present alternatives against agreed constraints, include the observed failure, and distinguish measured outcomes from estimates.","rationales":{"a":"It obscures a failure relevant to approval.","b":"Implementation detail alone does not compare decision consequences.","c":"The board can see the trade-offs and act on them.","d":"A sampled failure still informs a decision under uncertainty."}}'),
  ('architect-professional', 1, 'handoff-artifacts', 'handoff-artifacts', '2026-07.v1', 6, 4, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"Municipal records system","prompt":"A new team must operate a system that retrieves policy excerpts and sends ambiguous cases to staff. What documentation makes the critical behavior reproducible?","options":[["a","Version the data flow, control boundaries, failure replays and ownership."],["b","Send the project charter and a link to the current model docs."],["c","Save screenshots of successful chats as the sole reference."],["d","Document only the retrieval index parameters, since the application is already deployed."]]}', '{"correct":["a"],"explanation":"Capture data flow, boundaries, failure handling, ownership and executable examples linked to deployed versions.","rationales":{"a":"The receiving team can inspect and reproduce critical behavior.","b":"These do not describe the implemented system or exception ownership.","c":"Screenshots omit wiring, versions and failure paths.","d":"Staff and runtime handoff behavior remains unspecified."}}'),
  ('architect-professional', 1, 'diagnose-permission-change', 'diagnose-permission-change', '2026-07.v1', 7, 3, 'https://platform.claude.com/docs/en/api/errors', '{"scenario":"Northline on-call","prompt":"After a deployment, all tool writes from one worker are denied. Reads still work and the old release passed. What should the on-call team compare first?","options":[["a","Add write instructions to the worker’s prompt."],["b","Switch models and compare how often the worker retries."],["c","Grant broad write access temporarily and look for further errors."],["d","Compare the worker identity, tool scope and denial trace with the prior release."]]}', '{"correct":["d"],"explanation":"Trace the effective identity and permission decision against the last known-good configuration.","rationales":{"a":"The service has already denied the attempted write.","b":"Retries do not diagnose an authorization decision.","c":"That weakens the boundary before identifying the cause.","d":"This isolates the changed permission path without widening access."}}'),
  ('architect-professional', 1, 'permit-routing', 'permit-routing', '2026-07.v1', 1, 3, 'https://www.anthropic.com/research/building-effective-agents', '{"scenario":"Coastal permits office","prompt":"Permit inquiries require a fixed eligibility check. Unusual zoning questions need variable read-only research. Issuance must always follow staff approval. Which architecture best fits?","options":[["a","Give a general agent research and issuance tools, with a written instruction to wait for staff."],["b","Use a fixed workflow for eligibility and approval, with a scoped research branch for unusual questions."],["c","Require each permit type to use the same list of fixed source searches."],["d","Allow automatic issuance when two research workers agree."]]}', '{"correct":["b"],"explanation":"Put fixed eligibility and issuance gates in code and allow bounded research where sequencing is uncertain.","rationales":{"a":"Issuance remains within the agent’s capability before a verified approval.","b":"The variable work is isolated from mandatory control points.","c":"It may miss the variable evidence needed for unusual zoning cases.","d":"Agreement cannot replace staff approval."}}'),
  ('architect-professional', 1, 'maintenance-budget', 'maintenance-budget', '2026-07.v1', 2, 1, 'https://platform.claude.com/docs/en/models/overview', '{"scenario":"Harbor power operator","prompt":"A tested route needs at least 96% accuracy and p95 below 3 seconds. Model A reaches 92% and 1.5 seconds. Model B reaches 97% and 2.4 seconds within budget. Model C reaches 99% and 4 seconds. Which baseline should the architect propose?","options":[["a","Use A and tune on live incidents because it has the lowest tail latency."],["b","Use C and report median latency in place of p95."],["c","Use B and confirm the thresholds on representative rollout traffic."],["d","Use all three on every case and select whichever finishes first."]]}', '{"correct":["c"],"explanation":"Choose a baseline meeting all measured constraints and monitor the same metrics in production.","rationales":{"a":"A misses the required accuracy before tuning.","b":"The acceptance criterion specifies p95.","c":"B meets both thresholds and budget in the trial.","d":"The fast answer can come from a model below the quality threshold."}}'),
  ('architect-professional', 1, 'drawing-index', 'drawing-index', '2026-07.v1', 3, 6, 'https://www.anthropic.com/research/contextual-retrieval', '{"scenario":"Coastal engineering archive","prompt":"Inspectors search by exact drawing identifier and by descriptions of structural features. A keyword-only system reliably finds identifiers but misses paraphrases. Which change preserves its strength while improving recall?","options":[["a","Merge lexical and semantic results and measure recall for both query types."],["b","Replace keyword search with semantic search and measure total clicks."],["c","Index only drawing titles and keep the current keyword search."],["d","Retrieve the latest drawings for every question and ask Claude to rank them."]]}', '{"correct":["a"],"explanation":"Keep the exact-ID signal and add a semantic path. Compare both query types on labeled cases.","rationales":{"a":"It retains current retrieval strengths while testing the gap.","b":"It can lose exact-ID performance and clicks do not establish recall.","c":"It reduces coverage of descriptions and paraphrases.","d":"Recency does not identify a requested drawing or feature."}}'),
  ('architect-professional', 1, 'appeals-canary', 'appeals-canary', '2026-07.v1', 4, 3, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"Harbor membership desk","prompt":"A candidate reduces p95, but a holdout shows more wrong referrals for appeals. What rollout evidence should decide promotion?","options":[["a","Compare all referrals from different months and use the larger total as success."],["b","Ship only to nonappeal cases and claim the result generalizes to appeals."],["c","Use only overall accuracy as the gate because appeals are infrequent."],["d","Randomize eligible cases and set a separate rollback threshold for appeals errors."]]}', '{"correct":["d"],"explanation":"A controlled comparison must retain a gate on the affected category and define a response to regression.","rationales":{"a":"The comparison confounds release with season and traffic.","b":"The affected segment is absent from the evidence.","c":"Overall accuracy can mask further appeal regressions.","d":"This protects the observed weak group and tests the candidate under comparable conditions."}}'),
  ('architect-professional', 1, 'supplier-disputes', 'supplier-disputes', '2026-07.v1', 5, 3, 'https://platform.claude.com/docs/en/test-and-evaluate/strengthen-guardrails/mitigate-jailbreaks', '{"scenario":"Harbor procurement","prompt":"An order assistant proposes credits from disputed receipts. Staff must resolve conflicting evidence and authorize the exact credit before issuance. Which two controls satisfy the requirement?","options":[["a","Approve any amount automatically when both models agree."],["b","Show staff both source records and the proposed amount for disputed cases."],["c","Record receipt numbers but permit edits after the approval without checking the version."],["d","Run a weekly audit and correct disputed credits after posting."],["e","Enforce an authorized approval for the exact credit version before the service issues it."]]}', '{"correct":["b","e"],"explanation":"Provide reviewers with the disagreement and bind their recorded approval to the exact downstream action.","rationales":{"a":"Model agreement is not staff approval.","b":"This lets the reviewer examine the actual disagreement.","c":"The record no longer proves which credit was approved.","d":"Audit is retrospective.","e":"This makes the decision traceable and binding."}}'),
  ('architect-professional', 1, 'handoff-thresholds', 'handoff-thresholds', '2026-07.v1', 6, 3, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"Marina service portal","prompt":"The sponsor wants faster responses. Staff require a named owner for escalations. A spending cap applies even in peak season. What belongs in the pilot agreement?","options":[["a","Agree only on total requests answered and use it as the shared metric."],["b","Set latency and cost thresholds, name the escalation owner, and agree when to pause the pilot."],["c","Let engineering and operations keep separate private goals and reconcile at the end."],["d","Agree on an average latency target and defer spend measurement until expansion."]]}', '{"correct":["b"],"explanation":"Capture thresholds, operational ownership, and stop conditions before interpreting outcomes.","rationales":{"a":"Volume omits the escalation and spend requirements.","b":"All the stated requirements are measurable or assigned.","c":"That defers decisions about what counts as acceptable.","d":"A hard spending cap needs monitoring during the pilot."}}'),
  ('architect-professional', 1, 'write-restriction', 'write-restriction', '2026-07.v1', 7, 1, 'https://code.claude.com/docs/en/settings', '{"scenario":"Coastal systems group","prompt":"A shared release procedure is useful to all repositories. A restriction on writing to production must remain in force regardless of project settings. How should these be delivered?","options":[["a","Share the workflow as a Skill and enforce production write limits centrally."],["b","Put both into a single user-level instruction file copied during onboarding."],["c","Put both in a repository Skill and require maintainers to remember to invoke it."],["d","Place the restriction in the release ticket template and audit a sample of releases."]]}', '{"correct":["a"],"explanation":"Package shared instructions for reuse and enforce mandatory restrictions at managed configuration and the service.","rationales":{"a":"The reusable workflow and mandatory boundary have appropriate scopes.","b":"The organization cannot guarantee that individuals retain or apply it.","c":"Optional invocation cannot enforce production restrictions.","d":"The template supplies guidance, not preventive enforcement."}}'),
  ('architect-professional', 1, 'library-pilot-stop', 'library-pilot-stop', '2026-07.v1', 6, 3, 'https://www.anthropic.com/research/demystifying-evals-for-ai-agents', '{"scenario":"Regional library lending","prompt":"A pilot targets p95 under 3 seconds and zero automatic overrides of restricted loans. One candidate runs at 2.1 seconds, but two overrides slipped through. Which decision should the library board record?","options":[["a","Hold the rollout until a pre-action control passes the override cases, then confirm p95 again."],["b","Approve the rollout and review any further overrides after the first week."],["c","Approve because the p95 result gives room for occasional staff intervention."],["d","Raise the p95 target and keep the current permission behavior."]]}', '{"correct":["a"],"explanation":"A blocking safety condition governs release alongside the performance target.","rationales":{"a":"The revised system must meet both conditions.","b":"The measured failures already violate the gate.","c":"The latency headroom does not authorize overrides.","d":"Changing a speed target does not address the policy failure."}}');
